COLLDATA("sh148","ar",[[1,"حَدثنَا عُثْمَان قَالَ سَمِعت أَحْمد بن صَالح يَقُول بن جريج إِذا أخبر الْخَبَر فَهُوَ جيد وَإِذا لم يخبر فَلَا يعبأ بِهِ"],[2,"قلت فَصَالح بن أبي الْأَخْضَر فَقَالَ لَيْسَ بِشَيْء فِي الزُّهْرِيّ"],[3,"قلت فمحمد بن أبي حَفْصَة قَالَ صُوَيْلِح لَيْسَ بِالْقَوِيّ"],[4,"قلت فَابْن جريج فَقَالَ لَيْسَ بِشَيْء فِي الزُّهْرِيّ"],[5,"فجعفر بن برْقَان فَقَالَ ضَعِيف فِي الزُّهْرِيّ"],[6,"قلت فمحمد بن إِسْحَاق فَقَالَ لَيْسَ بِهِ بَأْس وَهُوَ ضَعِيف الحَدِيث عَن الزُّهْرِيّ"],[7,"قلت لَهُ وَالزهْرِيّ أحب إِلَيْك فِي سعيد بن الْمسيب أَو قَتَادَة فَقَالَ كِلَاهُمَا"],[8,"قلت فهما أحب إِلَيْك أَو يحيى بن سعيد فَقَالَ كل ثِقَة"],[9,"قلت لَهُ عبد الرَّحْمَن بن إِسْحَاق الَّذِي يروي عَن الزُّهْرِيّ فَقَالَ صَالح"],[10,"وَسَأَلته عَن سُفْيَان بن حُسَيْن فَقَالَ ثِقَة وَهُوَ ضَعِيف الحَدِيث عَن الزُّهْرِيّ"],[11,"قلت لَهُ فمعمر أحب إِلَيْك أَو يُونُس فَقَالَ معمر"],[12,"قلت فيونس أحب إِلَيْك أَو عقيل فَقَالَ يُونُس ثِقَة وَعقيل ثِقَة نبيل الحَدِيث عَن الزُّهْرِيّ"],[13,"وَسَأَلته عَن الْأَوْزَاعِيّ مَا حَاله فِي الزُّهْرِيّ فَقَالَ ثِقَة"],[14,"قلت لَهُ أَيْن يَقع من يُونُس فَقَالَ يُونُس أسْند عَن الزُّهْرِيّ وَالْأَوْزَاعِيّ ثِقَة مَا أقل مَا روى الْأَوْزَاعِيّ عَن الزُّهْرِيّ"],[15,"حَدثنَا عُثْمَان قَالَ سَمِعت أَحْمد بن صَالح يَقُول نَحن لَا نقدم فِي الزُّهْرِيّ على يُونُس أحدا قَالَ أَحْمد سَمِعت أَحَادِيث يُونُس عَن الزُّهْرِيّ فَوجدت الحَدِيث الْوَاحِد رُبمَا سَمعه من الزُّهْرِيّ مرَارًا قَالَ أَحْمد وَكَانَ الزهرى إِذا قدم أَيْلَة نزل على يُونُس وَإِذا سَار إِلَى الْمَدِينَة زامله يُونُس"],[16,"قلت ليحيى فزياد بن سعد أَي شَيْء حَاله فِي الزُّهْرِيّ فَقَالَ ثِقَة"],[17,"قلت فَمَا حَال سُلَيْمَان بن مُوسَى فِي الزُّهْرِيّ فَقَالَ ثِقَة"],[18,"قلت فعبد الله بن عبد الرَّحْمَن الجُمَحِي كَيفَ حَدِيثه عَن بن شهَاب فَقَالَ لَا أعرفهُ"],[19,"قلت فعنبسة بن مهْرَان عَن الزُّهْرِيّ من عَنْبَسَة يروي عَنهُ يحيى بن المتَوَكل فَقَالَ لَا أعرفهُ"],[20,"قلت فعمر بن عُثْمَان الَّذِي يروي عَن أَبِيه عَن بن شهَاب مَا حَالهمَا فَقَالَ مَا أَعْرفهُمَا"],[21,"قلت فَابْن أبي ذِئْب مَا حَاله فِي الزُّهْرِيّ فَقَالَ بن أبي ذِئْب ثِقَة"],[22,"وَسَأَلته عَن أخي الزُّهْرِيّ كَيفَ حَدِيثه قَالَ ثِقَة"],[23,"حَدثنَا عُثْمَان قَالَ سَمِعت أَحْمد بن صَالح يَقُول هُوَ يروي عَن الزُّهْرِيّ وَالزهْرِيّ يروي عَنهُ"],[24,"قلت ليحيى فَابْن أخي الزُّهْرِيّ مَا حَاله فَقَالَ ضَعِيف حَدثنَا عُثْمَان قَالَ سَأَلت يحيى بن معِين عَن أَصْحَاب قَتَادَة قلت لَهُ"],[25,"الدستوَائي أحب إِلَيْك فِي قَتَادَة أَو سعيد فَقَالَ كِلَاهُمَا"],[26,"قلت فهمام أحب إِلَيْك عَن قَتَادَة أَو أبان فَقَالَ مَا أقربهما كِلَاهُمَا ثبتان"],[27,"قلت فسليمان التيمى فَقَالَ ثِقَة"],[28,"قلت فحماد بن سَلمَة فَقَالَ ثِقَة"],[29,"قلت فحماد أحب إِلَيْك أم أَبُو هِلَال فَقَالَ حَمَّاد أحب إِلَيّ وَأَبُو هِلَال صَدُوق"],[30,"قلت فَأَبُو عوَانَة فَقَالَ قريب من حَمَّاد"],[31,"قلت فهمام أحب إِلَيْك فِي قَتَادَة أَو أَبُو عوَانَة فَقَالَ همام أحب إِلَيّ من أبي عوَانَة"],[32,"قلت فعمر بن إِبْرَاهِيم فَقَالَ ثِقَة"],[33,"قلت فالحجاج أَعنِي بن أَرْطَأَة فَقَالَ صَالح"],[34,"قلت فسويد أَبُو حَاتِم مَا حَاله فِي قَتَادَة فَقَالَ أَرْجُو أَن لَا يكون بِهِ بَأْس"],[35,"قلت فسعيد بن بشير فَقَالَ ضَعِيف"],[36,"حَدثنَا عُثْمَان قَالَ وَسمعت دحيما يوثق سعيد بن بشير"],[37,"قلت ليحيى شُعْبَة أحب إِلَيْك فِي قَتَادَة أم هِشَام فَقَالَ كِلَاهُمَا قَالَ عُثْمَان هِشَام أَكثر من شُعْبَة فِي قَتَادَة حَدثنَا أَبُو سعيد قَالَ سَأَلت يحيى بن معِين عَن أَصْحَاب الْأَعْمَش قلت"],[38,"سُفْيَان أحب إِلَيْك فِي الْأَعْمَش أَو شُعْبَة فَقَالَ سُفْيَان أحب إِلَيّ فِي الْأَعْمَش"],[39,"قلت فزهير أحب إِلَيْك أم زَائِدَة فَقَالَ كِلَاهُمَا يَعْنِي ثَبت"],[40,"قلت فَأَبُو مُعَاوِيَة أحب إِلَيْك فِيهِ أم وَكِيع فَقَالَ أَبُو مُعَاوِيَة أعلم بِهِ ووكيع ثِقَة"],[41,"قلت فجرير أحب إِلَيْك أَو بن نمير فَقَالَ كِلَاهُمَا"],[42,"قلت وَابْن إِدْرِيس أحب إِلَيْك أَو بن نمير فَقَالَ كِلَاهُمَا ثقتان إِلَّا أَن بن إِدْرِيس أرفع وَهُوَ ثِقَة فِي كل شَيْء"],[43,"قلت فَأَبُو عوَانَة أحب فِيهِ أَو عبد الْوَاحِد فَقَالَ أَبُو عوَانَة أحب إِلَيّ وَعبد الْوَاحِد ثِقَة"],[44,"قلت وَأَبُو شهَاب أحب إِلَيْك فِيهِ أَو أَبُو بكر بن عَيَّاش فَقَالَ أَبُو شهَاب أحب إِلَيّ من أبي بكر فِي كل شَيْء"],[45,"قلت فَأَبُو بكر أحب إِلَيْك فِيهِ أَو أَبُو الْأَحْوَص فَقَالَ مَا أقربهما"],[46,"قلت فقطبة وَحَفْص فَقَالَ ثقتان"],[47,"قلت فشيبان مَا حَاله فِي الْأَعْمَش فَقَالَ ثِقَة فِي كل شَيْء"],[48,"قلت فيزيد بن عبد الْعَزِيز بن سياه فَقَالَ ثِقَة"],[49,"قلت فَأَبُو عُبَيْدَة فِي الْأَعْمَش أَبُو مُحَمَّد بن أبي عُبَيْدَة فَقَالَ لَيْسَ لي بِهِ وبأبيه علم"],[50,"قلت فعيسى بن يُونُس أحب إِلَيْك أَو أَبُو مُعَاوِيَة فَقَالَ ثِقَة وثقة حَدثنَا عُثْمَان قَالَ سَأَلت يحيى عَن أَصْحَاب أَيُّوب السّخْتِيَانِيّ قلت"],[51,"حَمَّاد بن زيد أحب إِلَيْك فِي أَيُّوب أَو بن علية قَالَ حَمَّاد بن زيد"],[52,"قلت فعبد الْوَارِث فَقَالَ مثل حَمَّاد قَالَ عُثْمَان بن سعيد لم يكن كَمَا قَالَ لِأَن عبد الْوَارِث كَانَ يرْمى بِالْقدرِ إِلَّا أَنه كَانَ متقنا"],[53,"قلت فالثقفي فَقَالَ ثِقَة"],[54,"قلت هُوَ أحب إِلَيْك فِي أَيُّوب أَو عبد الْوَارِث فَقَالَ عبد الْوَارِث"],[55,"قلت فَابْن عُيَيْنَة أحب إِلَيْك فِي أَيُّوب أَو عبد الْوَارِث فَقَالَ عبد الْوَارِث"],[56,"قلت لَهُ مَا حَال وهيب فِي أَيُّوب فَقَالَ ثِقَة"],[57,"قلت فَهُوَ أحب إِلَيْك أم الثَّقَفِيّ فَقَالَ ثِقَة وثقة أَخْبرنِي عُثْمَان قِرَاءَة عَلَيْهِ قَالَ سَأَلت يحيى بن معِين عَن أَصْحَاب عَمْرو بن دِينَار قلت لَهُ"],[58,"بن عُيَيْنَة أحب إِلَيْك فِي عَمْرو أَو الثَّوْريّ فَقَالَ بن عُيَيْنَة أعلم بِهِ"],[59,"قلت فَابْن عُيَيْنَة أَو حَمَّاد بن زيد فَقَالَ بن عُيَيْنَة أعلم بِهِ"],[60,"قلت فشعبة فَقَالَ وَأي شَيْء روى عَنهُ شُعْبَة إِنَّمَا روى عَنهُ نَحْو مائَة حَدِيث أَو كَمَا قَالَ أَخْبرنِي عُثْمَان قَالَ سَأَلت يحيى بن معِين عَن أَصْحَاب الشّعبِيّ قلت"],[61,"إِسْمَاعِيل بن أبي خَالِد أحب إِلَيْك فِي الشّعبِيّ أم الشَّيْبَانِيّ فَقَالَ بن أبي خَالِد والشيباني ثِقَة"],[62,"قلت فراس أحب إِلَيْك أم بَيَان فَقَالَ كِلَاهُمَا ثقتان"],[63,"قلت فزكريا أحب إِلَيْك أَو بن ليلى فَقَالَ زَكَرِيَّا أحب إِلَيّ فِي كل شَيْء بن أبي ليلى ضَعِيف"],[64,"قلت فَابْن عون فِيمَا روى عَن إِبْرَاهِيم وَالشعْبِيّ فَقَالَ هُوَ فِي كل شَيْء ثِقَة"],[65,"قلت هُوَ أحب إِلَيْك فِي الشّعبِيّ أَو إِسْمَاعِيل فَقَالَ إِسْمَاعِيل أعلم بِهِ أَخْبرنِي عُثْمَان قَالَ سَأَلت يحيى بن معِين عَن أَصْحَاب إِبْرَاهِيم قلت"],[66,"الْأَعْمَش أحب إِلَيْك فِي إِبْرَاهِيم أَو مَنْصُور فَقَالَ مَنْصُور أحب إِلَيّ"],[67,"قلت لَهُ فمنصور أحب إِلَيْك فِيهِ أَو الحكم فَقَالَ مَنْصُور"],[68,"قلت فمنصور أَو الْمُغيرَة فَقَالَ مَنْصُور"],[69,"قلت وَالْحكم أحب إِلَيْك فِيهِ أَو الفضيل بن عَمْرو فَقَالَ الحكم أعلم بِهِ"],[70,"قلت فحماد بن أبي سُلَيْمَان أحب إِلَيْك أَو شباك فَقَالَ شباك أحب إِلَيّ وَحَمَّاد ثِقَة"],[71,"قلت فَمحل فَقَالَ ثِقَة"],[72,"قلت فالحسن بن عَمْرو الْفُقيْمِي فَقَالَ ثِقَة"],[73,"قلت فمعرف بن وَاصل فَقَالَ ثِقَة"],[74,"قَالَ وَسَأَلته عَن عُبَيْدَة قلت مَا حَاله فِي إِبْرَاهِيم النَّخعِيّ فَقَالَ عُبَيْدَة لَيْسَ حَدِيثه بِشَيْء أَخْبرنِي أَبُو سعيد قَالَ سَأَلت يحيى بن معِين عَن أَصْحَاب أبي إِسْحَاق السبيعِي قلت"],[75,"شُعْبَة أحب إِلَيْك فِي أَبى إِسْحَاق أَو سُفْيَان فَقَالَ سُفْيَان قلت فهما أم زُهَيْر فَقَالَ مَا أحد أعلم بِأبي إِسْحَاق من سُفْيَان وَشعْبَة"],[76,"قلت فشريك أحب إِلَيْك أَو إِسْرَائِيل فَقَالَ شريك أحب إِلَيّ وَهُوَ أقدم وَإِسْرَائِيل صَدُوق"],[77,"قلت فَأَبُو الْأَحْوَص أحب إِلَيْك فِيهِ أَو أَبُو بكر بن عَيَّاش فَقَالَ مَا أقربهما"],[78,"وَسَأَلته عَن يُونُس بن أبي إِسْحَاق فَقَالَ ثِقَة أَخْبرنِي عُثْمَان قَالَ سَأَلت يحيى قلت"],[79,"جرير أحب إِلَيْك فِي مَنْصُور أَو شريك فَقَالَ جرير أعلم بِهِ"],[80,"قلت فشريك أحب إِلَيْك فِي مَنْصُور أَو أَبُو الْأَحْوَص فَقَالَ شريك أعلم بِهِ قَالَ أَبُو سعيد أرَاهُ قَالَ وَكم روى أَبُو الْأَحْوَص عَن مَنْصُور أَخْبرنِي عُثْمَان قَالَ سَأَلت يحيى بن معِين عَن أَصْحَاب سُفْيَان قلت"],[81,"يحيى أحب إِلَيْك فِي سُفْيَان أَو عبد الرَّحْمَن بن مهْدي فَقَالَ يحيى"],[82,"قلت فعبد الرَّحْمَن أحب إِلَيْك أَو وَكِيع فَقَالَ وَكِيع"],[83,"قلت فوكيع أحب إِلَيْك أَو أَبُو نعيم فَقَالَ وَكِيع"],[84,"قلت فالأشجعي فَقَالَ صَالح"],[85,"قلت فمعاوية بن هِشَام فَقَالَ صَالح وَلَيْسَ بِذَاكَ"],[86,"قلت والزبيري أَعنِي أَبَا أَحْمد فَقَالَ لَيْسَ بِهِ بَأْس"],[87,"قلت وَأَبُو إِسْحَاق الْفَزارِيّ فَقَالَ ثِقَة ثِقَة"],[88,"قلت وَأَبُو دَاوُد الْحَفرِي فَقَالَ ثِقَة"],[89,"قلت فيحيى بن يمَان فَقَالَ أَرْجُو أَن يكون صَدُوقًا قلت فَكيف هُوَ فِي حَدِيثه فَقَالَ لَيْسَ بِالْقَوِيّ"],[90,"قلت فعبيد الله بن مُوسَى فَقَالَ ثِقَة مَا أقربه من بن الْيَمَان"],[91,"قلت فقبيصة فَقَالَ مثل عبيد الله"],[92,"قلت فالفاريابي قَالَ مثلهم"],[93,"قلت فعبد الرَّزَّاق فِي سُفْيَان فَقَالَ مثلهم"],[94,"قلت وَأَبُو حُذَيْفَة فَقَالَ مثلهم"],[95,"قلت فيعلى فَقَالَ ضَعِيف فِي سُفْيَان ثِقَة فِي غَيره أَخْبرنِي عُثْمَان قَالَ سَأَلت يحيى بن معِين عَن أَصْحَاب شُعْبَة قلت"],[96,"يحيى أحب إِلَيْك فِي شُعْبَة أَو يزِيد بن زُرَيْع فَقَالَ ثقتان"],[97,"قلت فغندر أحب إِلَيْك أَو مُحَمَّد بن أبي عدي فَقَالَ ثقتان"],[98,"قلت فَأَبُو دَاوُد أحب إِلَيْك أَو حرمي بن عمَارَة فَقَالَ أَبُو دَاوُد صَدُوق أَبُو دَاوُد أحب إِلَيّ مِنْهُ قلت فَأَبُو دَاوُد أحب إِلَيْك فِيهِ أَو عبد الرَّحْمَن بن مهْدي فَقَالَ أَبُو دَاوُد أعلم بِهِ"],[99,"قلت فشبابة قَالَ ثِقَة"],[100,"قلت فمعاذ أثبت فِي شُعْبَة أم غنْدر فَقَالَ ثِقَة وثقة"],[101,"قَالَ لنا أَبُو سعيد عبد الرَّحْمَن أحب إِلَيْنَا فِي كل شَيْء وَأَبُو دَاوُد أَكثر رِوَايَة عَن شُعْبَة أَخْبرنِي عُثْمَان قَالَ قلت ليحيى بن معِين"],[102,"إِبْرَاهِيم بن ميسرَة مَا حَاله فَقَالَ ثِقَة"],[103,"قلت هُوَ أحب إِلَيْك عَن طَاوس أَو بن طَاوس فَقَالَ كِلَاهُمَا"],[104,"وَسَأَلته عَن أَشْعَث بن عبد الرَّحْمَن الْجرْمِي قَالَ ثِقَة"],[105,"قلت وَأَبوهُ فَقَالَ ثِقَة"],[106,"قلت الْأَسْقَع بن الأسلع مَا حَاله فَقَالَ ثِقَة"],[107,"وَسَأَلته عَن أسلم الْعجلِيّ فَقَالَ ثِقَة"],[108,"قلت فالأسود بن مَسْعُود فَقَالَ ثِقَة"],[109,"وَسَأَلته عَن أُسَامَة بن زيد أَعنِي اللَّيْثِيّ فَقَالَ لَيْسَ بِهِ بَأْس"],[110,"قلت فأدم بن عَليّ مَا حَاله فَقَالَ ثِقَة"],[111,"وَسَأَلته عَن الْأَصْبَغ بن زيد الْوراق فَقَالَ ثِقَة"],[112,"وَسَأَلته عَن إِسْمَاعِيل بن مُسلم الْمَكِّيّ فَقَالَ لَيْسَ بِشَيْء"],[113,"قلت فإسماعيل بن مُسلم الْعَبْدي فَقَالَ ثِقَة"],[114,"قلت أَيُّوب بن عتبَة أحب إِلَيْك أَو عِكْرِمَة بن عمار فَقَالَ عِكْرِمَة أحب إِلَيّ أَيُّوب ضَعِيف"],[115,"وَسَأَلته عَن أَيُّوب بن جَابر فَقَالَ لَيْسَ بِشَيْء"],[116,"وَسَأَلته عَن أبان بن عبد الله البَجلِيّ فَقَالَ ثِقَة"],[117,"قلت فأشعث السمان فَقَالَ لَيْسَ بِثِقَة"],[118,"وَسَأَلته عَن إِبْرَاهِيم بن الزبْرِقَان فَقَالَ ثِقَة"],[119,"قلت أَيُّوب أحب إِلَيْك عَن نَافِع أَو عبيد الله فَقَالَ كِلَاهُمَا وَلم يفضل"],[120,"قلت فأسامة بن زيد الصَّغِير أَعنِي بن أسلم فَقَالَ ضَعِيف"],[121,"قَالَ وَشعْبَة يَقُول أُسَامَة بن زيد الصَّغِير لَيْسَ هُوَ اللَّيْثِيّ الَّذِي يروي عَنهُ جَعْفَر بن عون وَغَيره إِنَّمَا هم ثَلَاثَة أُسَامَة بن زيد وَعبد الله بن زيد وَعبد الرَّحْمَن بن زيد"],[122,"وَسَأَلته عَن أَفْلح بن حميد فَقَالَ ثِقَة"],[123,"وَسَأَلته عَن إِبْرَاهِيم بن نَافِع كَيفَ حَدِيثه فَقَالَ ثِقَة"],[124,"قلت فإسماعيل بن جَعْفَر الْمَدِينِيّ كَيفَ هُوَ فَقَالَ ثِقَة"],[125,"وَسَأَلته عَن إِيَاس بن سَلمَة فَقَالَ ثِقَة"],[126,"وَسَأَلته عَن أَيُّوب بن سُوَيْد أَعنِي الرَّمْلِيّ قَالَ لَيْسَ بِشَيْء"],[127,"قلت فإسماعيل بن عَيَّاش كَيفَ هُوَ عنْدك فَقَالَ أَرْجُو أَن لَا يكون بِهِ بَأْس"],[128,"وَسَأَلته عَن أَرْطَأَة بن الْمُنْذر كَيفَ حَدِيثه فَقَالَ ثِقَة"],[129,"قلت فإسحاق بن مَنْصُور السَّلُولي فَقَالَ لَيْسَ بِهِ بَأْس"],[130,"قلت فإسحاق الْأَزْرَق فَقَالَ ثِقَة"],[131,"قلت إِسْحَاق أحب إِلَيْك أَو بن مسْهر فَقَالَ بن مسْهر أحب إِلَيّ"],[132,"قلت وَابْن مسْهر أحب إِلَيْك أَو يحيى بن زَكَرِيَّا فَقَالَ كِلَاهُمَا ثقتان"],[133,"وَسَأَلته عَن أُميَّة بن هِنْد فَقَالَ لَا أعرفهُ"],[134,"وَسَأَلته عَن أَسْبَاط بن نصر فَقَالَ ثِقَة"],[135,"وَسَأَلته عَن إِسْمَاعِيل بن إِبْرَاهِيم بن مهَاجر كَيفَ هُوَ فَقَالَ ضَعِيف"],[136,"فإياس بن دَغْفَل كَيفَ حَدِيثه فَقَالَ ثِقَة"],[137,"قلت فالأصبغ بن سُفْيَان كَيفَ حَدِيثه فَقَالَ لَا أعرفهُ"],[138,"قلت فالأصبغ بن نباتة فَقَالَ لَيْسَ بِشَيْء"],[139,"قلت فإبراهيم بن إِسْمَاعِيل بن أبي حَبِيبَة فَقَالَ صَالح"],[140,"قلت فأبان بن صَالح كَيفَ حَدِيثه فَقَالَ ثِقَة"],[141,"قلت فيونس بن أبي إِسْحَاق أحب إِلَيْك أَو إِسْرَائِيل فَقَالَ كل ثِقَة"],[142,"وَسَأَلته عَن إِسْمَاعِيل بن أَوسط كَيفَ حَدِيثه فَقَالَ ثِقَة"],[143,"قلت فأنس بن عِيَاض مَا حَاله فَقَالَ لَيْسَ بِهِ بَأْس"],[144,"قلت فإسماعيل بن أبي حَكِيم فَقَالَ ثِقَة"],[145,"قلت فإبراهيم بن مهَاجر بن مِسْمَار تعرفه فَقَالَ صَالح لَيْسَ بِهِ بَأْس"],[146,"قلت يروي عَن صَالح أبي بشر السدُوسِي من هُوَ فَقَالَ لَا أعرفهُ"],[147,"قلت فأيوب بن وَاصل صَاحب الْفراء تعرفه فَقَالَ مَا أعرفهُ"],[148,"وَسَأَلته عَن إِسْحَاق بن جَعْفَر فَقَالَ مَا أرَاهُ إِلَّا كَانَ صَدُوقًا"],[149,"قلت فإسحاق بن حَازِم مَا حَاله فَقَالَ ثِقَة"],[150,"قلت فإبراهيم بن أبي حَيَّة فَقَالَ شيخ ثِقَة"],[151,"قلت فإسماعيل بن سميع فَقَالَ ثِقَة"],[152,"قلت عَن عَليّ بن أبي كثير من على فَقَالَ ثِقَة"],[153,"قلت فإبراهيم الهجري كَيفَ حَدِيثه فَقَالَ لَيْسَ بِشَيْء"],[154,"وَسَأَلته عَن أبان بن صمعة فَقَالَ ثِقَة"],[155,"قلت وَإِسْمَاعِيل بن سَالم كَيفَ حَدِيثه فَقَالَ ثِقَة"],[156,"قلت هُوَ أحب إِلَيْك أوابن أبي خَالِد فَقَالَ كِلَاهُمَا ثِقَة قَالَ لنا عُثْمَان بن سعيد إِسْمَاعِيل خير مِنْهُ بِكَثِير"],[157,"قلت فإبراهيم بن على الرَّافِعِيّ من هُوَ فَقَالَ شيخ مَاتَ بِالْقربِ كَانَ هَا هُنَا لَيْسَ بِهِ بَأْس"],[158,"قلت يَقُول حَدثنِي عمي أَيُّوب بن حسن كَيفَ هُوَ فَقَالَ لَيْسَ بِهِ بَأْس"],[159,"قلت فأصرم بن حَوْشَب تعرفه فَقَالَ كَذَّاب خَبِيث"],[160,"قلت فأسباط بن مُحَمَّد كَيفَ حَدِيثه فَقَالَ لَيْسَ بِهِ بَأْس"],[161,"قلت عَن أبي رَجَاء الْخُرَاسَانِي من هُوَ فَقَالَ ثِقَة قَالَ لنا أَبُو سعيد هُوَ عبد الله بن وَاقد الْهَرَوِيّ"],[162,"وَسَأَلته عَن إِبْرَاهِيم بن رستم فَقَالَ ثِقَة"],[163,"سَمِعت يحيى وَسُئِلَ عَن آدم بن سُلَيْمَان الَّذِي يروي عَنهُ سُفْيَان قَالَ هُوَ أَبُو يحيى بن آدم مولى خَالِد بن سعيد بن الْعَاصِ"],[164,"وَسَأَلته عَن أَيمن بن نابل كَيفَ هُوَ فَقَالَ ثِقَة"],[165,"قلت فإسماعيل بن زَكَرِيَّا أحب إِلَيْك فِي الحَدِيث أَو يحيى بن زَكَرِيَّا فَقَالَ لم أَهما أَخَوان عنْدك قلت لَا وَلَكِنِّي أردْت فِي الحَدِيث فَقَالَ يحيى أحب إِلَيّ"],[166,"قلت أَزْهَر السمان كَيفَ حَدِيثه فَقَالَ ثِقَة"],[167,"قلت فأشرس بن حسان فَقَالَ ثِقَة"],[168,"قلت فإسحاق بن يحيى مَا حَاله الَّذِي يروي عَنهُ بن الْمُبَارك حَدِيث أبي بكر فَقَالَ لَيْسَ بِشَيْء"],[169,"قلت فالأجلح فَقَالَ ثِقَة"],[170,"وَسَأَلته عَن إِبْرَاهِيم بن طهْمَان فَقَالَ لَيْسَ بِهِ بَأْس"],[171,"وَسَأَلته عَن إِسْحَاق بن إِسْمَاعِيل قَالَ أَرْجُو أَن يكون صَدُوقًا"],[172,"فَأَبُو مُحَمَّد بن إِسْحَاق كَيفَ حَاله فَقَالَ ثِقَة"],[173,"قلت فعمه عبد الرَّحْمَن فَقَالَ ثِقَة"],[174,"قَالَ عُثْمَان بن سعيد وَرَأَيْت يحيى بن معِين يكْتب عَن إِبْرَاهِيم بن الْمُنْذر الْحزَامِي من أَحَادِيث بن وهب ظننتها الْمَغَازِي"],[175,"قلت ليحيى فَأَبُو إِسْرَائِيل مَا حَاله فَقَالَ ثِقَة قلت مَا اسْمه فَقَالَ إِسْمَاعِيل بن أبي إِسْحَاق"],[176,"حَدثنَا عُثْمَان قَالَ سَأَلت يحيى بن معِين عَن بشر بن شغَاف فَقَالَ ثِقَة"],[177,"وَسَأَلته عَن بكر بن سوَادَة فَقَالَ ثِقَة"],[178,"قلت بشر بن آدم مَا حَاله فَقَالَ لَا أعرفهُ"],[179,"وَسَأَلته عَن برد بن سِنَان فَقَالَ ثِقَة"],[180,"قلت بهْلُول بن رَاشد حَدثنَا عَنهُ القعْنبِي تعرفه فَقَالَ مَا أعرفهُ"],[181,"قلت فبقية بن الْوَلِيد كَيفَ حَدِيثه فَقَالَ ثِقَة"],[182,"قلت هُوَ أحب إِلَيْك أَو مُحَمَّد بن حَرْب فَقَالَ ثِقَة وثقة"],[183,"قَالَ أَبُو سعيد هُوَ مُحَمَّد بن حَرْب الْخَولَانِيّ الأبرش حمصي ثِقَة"],[184,"قلت فبشير بن سلمَان فَقَالَ ثِقَة"],[185,"قلت فبشير بن ثَابت الَّذِي يروي عَنهُ أَبُو بشر مَا حَاله فَقَالَ ثِقَة"],[186,"وَسَأَلته عَن بشر بن السّري فَقَالَ ثِقَة"],[187,"قلت فبكر بن سليم قَالَ حَدثنَا عبد الحكم قَالَ مَا أَعْرفهُمَا"],[188,"وَسَأَلته عَن بشار الْخفاف فَقَالَ لَيْسَ بِثِقَة"],[189,"قَالَ أَبُو سعيد بَلغنِي أَن عَليّ بن الْمَدِينِيّ كَانَ يحسن القَوْل فِي بشار الْخفاف هَذَا وَكَانَ من رَهْط أَحْمد بن حَنْبَل"],[190,"وَسَأَلته عَن بهز بن حَكِيم كَيفَ حَدِيثه فَقَالَ ثِقَة"],[191,"قلت لَهُ فبهز بن أَسد أحب إِلَيْك فِي حَمَّاد أَو عَفَّان فَقَالَ ثقتان حَدثنَا عُثْمَان قَالَ"],[192,"سَأَلت يحيى بن معِين عَن تَوْبَة الْعَنْبَري فَقَالَ ثِقَة"],[193,"قلت تَمام بن بزيع فَقَالَ لَيْسَ بِشَيْء حَدثنَا عُثْمَان قَالَ"],[194,"سَأَلت يحيى بن معِين عَن ثُمَامَة بن حزن فَقَالَ ثِقَة"],[195,"قلت فثور بن زيد الديلِي فَقَالَ ثِقَة"],[196,"قلت فثور بن يزِيد فَقَالَ ثِقَة"],[197,"قلت فثابت بن عجلَان كَيفَ حَدِيثه فَقَالَ ثِقَة حَدثنَا عُثْمَان قَالَ"],[198,"سَأَلت يحيى بن معِين عَن جَعْفَر بن مُحَمَّد بن عَليّ بن الْحُسَيْن فَقَالَ ثِقَة"],[199,"قلت فجابان مَا حَاله قَالَ مَا يروي عَنهُ إِلَّا ذَا"],[200,"وَسَأَلته عَن جُبَير بن أبي سُلَيْمَان بن جُبَير فَقَالَ ثِقَة"],[201,"قلت فجعفر بن برْقَان فَقَالَ ثِقَة"],[202,"وَسَأَلته عَن جهير بن يزِيد فَقَالَ ثِقَة"],[203,"قلت فجويرية بن أَسمَاء فَقَالَ ثِقَة"],[204,"وَسَأَلته عَن جَعْفَر بن عون كَيفَ حَدِيثه فَقَالَ ثِقَة"],[205,"قلت والجراح بن مليح البهراني الْحِمصِي فَقَالَ لَا أعرفهُ"],[206,"قلت فجويبر كَيفَ حَدِيثه فَقَالَ ضَعِيف"],[207,"قلت فجرثومة مَا حَاله فَقَالَ ثِقَة"],[208,"وَسَأَلته عَن جسر فَقَالَ لَيْسَ بِشَيْء قَالَ أَبُو سعيد هُوَ جسر بن الْحسن"],[209,"قلت فجابر الْجعْفِيّ لم يضعفونه فَقَالَ يضعفونه"],[210,"وَسُئِلَ عَن جَعْفَر الْأَحْمَر فَقَالَ بِيَدِهِ لم يلينه وَلم يُضعفهُ"],[211,"قلت لَهُ فَكيف بِحَدِيث جرير بن حَازِم فَقَالَ ثِقَة"],[212,"قلت فَأَبُو الوداك فَقَالَ ثِقَة قَالَ أَبُو سعيد هُوَ جبر بن نوف حَدثنَا عُثْمَان قَالَ"],[213,"سَأَلت يحيى بن معِين عَن حَكِيم بن رُزَيْق فَقَالَ ثِقَة"],[214,"قلت فالحجاج بن دِينَار فَقَالَ لَيْسَ بِهِ بَأْس"],[215,"قلت فَابْن أبي ذِئْب عَن خَاله الْحَارِث بن عبد الرَّحْمَن كَيفَ حَاله قَالَ هُوَ يرْوى عَنهُ وَهُوَ مَشْهُور"],[216,"وَسَأَلته عَن حسان بن عَطِيَّة كَيفَ حَاله فَقَالَ ثِقَة"],[217,"وَسَأَلته عَن حَنْظَلَة بن خويلد فَقَالَ ثِقَة"],[218,"وَسَأَلته عَن حزم فَقَالَ ثِقَة"],[219,"قلت فحماد النصيبي فَقَالَ لَيْسَ بِشَيْء"],[220,"وَسَأَلته عَن حسام بن مصك فَقَالَ لَيْسَ بِشَيْء"],[221,"وَسَأَلته عَن حُسَيْن الْمعلم فَقَالَ ثِقَة"],[222,"قلت فحماد الْأَبَح لَيْسَ بِشَيْء"],[223,"قلت فعوف عَن حَمْزَة أبي عمر من حَمْزَة فَقَالَ شيخ لَا يعرف"],[224,"وَسَأَلته أَي شَيْء حَال الْحَارِث فِي عَليّ فَقَالَ ثِقَة قَالَ أَبُو سعيد لَا يُتَابع عَلَيْهِ"],[225,"قلت حَارِثَة بن مضرب فَقَالَ ثِقَة"],[226,"وَسَأَلته عَن حَنْظَلَة الجُمَحِي كَيفَ حَدِيثه فَقَالَ ثِقَة"],[227,"وَسَأَلته عَن بن أبي الرِّجَال قَالَ أَيهمَا قلت هَذَا الَّذِي يروي عَنهُ الحكم بن مُوسَى فَقَالَ ثِقَة"],[228,"قلت فالآخر فَقَالَ لَيْسَ بِشَيْء يَعْنِي حَارِثَة بن أبي الرِّجَال وَالْأول عبد الرَّحْمَن بن أبي الرِّجَال"],[229,"وَسَأَلته عَن الْحُسَيْن بن ضَمرَة فَقَالَ لَيْسَ بِشَيْء"],[230,"قلت فحيي بن عَمْرو فَقَالَ لَيْسَ بِهِ بَأْس يَعْنِي الْمصْرِيّ"],[231,"قلت فحفص بن غيلَان فَقَالَ ثِقَة"],[232,"قلت فحريز بن عُثْمَان فَقَالَ ثِقَة"],[233,"وَسَأَلت يحيى قلت أَبُو أُسَامَة أحب إِلَيْك أَو عَبدة بن سُلَيْمَان فَقَالَ مَا مِنْهُمَا إِلَّا ثِقَة"],[234,"وَسَأَلته عَن حميد بن عبد الرَّحْمَن الرُّؤَاسِي فَقَالَ ثِقَة"],[235,"وَسَأَلته عَن منْدَل بن عَليّ فَقَالَ لَيْسَ بِهِ بَأْس"],[236,"قلت وَأَخُوهُ حبَان بن عَليّ فَقَالَ صَدُوق"],[237,"قلت أَيهمَا أحب إِلَيْك فَقَالَ كِلَاهُمَا وَتَمْرًا كَأَنَّهُ يضعفهما"],[238,"قلت لَهُ فعلي بن صَالح أحب إِلَيْك أَو الْحسن يَعْنِي بن صَالح فَقَالَ كِلَاهُمَا ثقتان"],[239,"وَسَأَلته عَن حبيب بن حبيب فَقَالَ من يروي عَنهُ قلت بن أبي شيبَة فَقَالَ لَا أعرفهُ"],[240,"وَسَأَلته عَن حَرْب بن عبيد الله الَّذِي يروي عَنهُ عَطاء بن السَّائِب فَقَالَ هُوَ مَشْهُور وَعَطَاء ثِقَة"],[241,"وَسَأَلته عَن يزِيد بن أبي زِيَاد فَقَالَ لَيْسَ بِالْقَوِيّ"],[242,"قلت فالحسن بن سُهَيْل الَّذِي يروي عَنهُ قَالَ مَشْهُور"],[243,"وَسَأَلته عَن الْحسن بن عبيد الله فَقَالَ لَيْسَ بِهِ بَأْس"],[244,"قلت فالحارث بن حصيرة مَا حَاله فَقَالَ خشبي ثِقَة"],[245,"وسمعته وَسُئِلَ عَن حجر بن عَنْبَس الَّذِي يروي عَنهُ سَلمَة فَقَالَ شيخ كُوفِي مَشْهُور"],[246,"وَسَأَلته عَن حبيب بن زيد الَّذِي يروي عَنهُ شُعْبَة مَا حَاله فَقَالَ ثِقَة"],[247,"وَسَأَلته عَن حمْرَان بن أعين كَيفَ هُوَ فَقَالَ ضَعِيف"],[248,"وَسَأَلته عَن حُسَيْن بن عبد الله الَّذِي يروي عَنهُ بن إِسْحَاق فَقَالَ ضَعِيف قلت فحسين بن عبد الله الَّذِي يروي عَنهُ بن جريج فَقَالَ هُوَ هُوَ"],[249,"وَسَأَلته عَن الْحَارِث بن يَعْقُوب كَيفَ هُوَ فَقَالَ ثِقَة"],[250,"قلت فحاتم بن إِسْمَاعِيل كَيفَ هُوَ فَقَالَ ثِقَة"],[251,"وَسَأَلته عَن حميد بن زِيَاد الْخَرَّاط فَقَالَ لَيْسَ بِهِ بَأْس"],[252,"قلت فحرملة بن عبد الْعَزِيز فَقَالَ لَيْسَ بِهِ بَأْس"],[253,"قلت فيروي حَرْمَلَة عَن عُثْمَان وَعمر ابْني مُضرس حَدِيث عَمْرو بن مرّة الْجُهَنِيّ من هما فَقَالَ مَا أَعْرفهُمَا"],[254,"قلت فَكيف حَدِيث عبد الحميد بن جَعْفَر فَقَالَ ثِقَة"],[255,"وَسَأَلته عَن حَارِثَة بن مُحَمَّد الَّذِي يروي عَن عمْرَة فَقَالَ لَيْسَ بِشَيْء"],[256,"قلت حُصَيْن الْجعْفِيّ تعرفه فَقَالَ مَا أعرفهُ"],[257,"قلت فحيان أَبُو النَّضر مَا حَاله فَقَالَ ثِقَة"],[258,"وَسَأَلته عَن حفصى بن ميسرَة الصَّنْعَانِيّ فَقَالَ ثِقَة"],[259,"قلت فحميد الشَّامي كَيفَ حَدِيثه الَّذِي يروي حَدِيث ثَوْبَان عَن سُلَيْمَان المنبهي فَقَالَ مَا أَعْرفهُمَا"],[260,"وَسَأَلته عَن حَفْص بن سُلَيْمَان الْأَسدي الْكُوفِي كَيفَ حَدِيثه فَقَالَ لَيْسَ بِثِقَة"],[261,"قلت يروي عَن كثير بن زَاذَان من هُوَ فَقَالَ لَا أعرفهُ"],[262,"وَسَأَلته عَن حَمْزَة بن الْمُغيرَة الْكُوفِي الَّذِي يروي عَنهُ بن عُيَيْنَة لَا تجْعَلُوا قَبْرِي وثنا مَا حَاله فَقَالَ لَيْسَ بِهِ بَأْس"],[263,"قلت فحسين الْجعْفِيّ فَقَالَ ثِقَة"],[264,"قلت والأشيب أَعنِي الْحسن بن مُوسَى فَقَالَ ثِقَة"],[265,"وَسَأَلته عَن حرمي بن عمَارَة بن أبي حَفْصَة كَيفَ هُوَ فَقَالَ صَدُوق"],[266,"قلت ليحيى بن معِين الْحسن لَقِي أَبَا هُرَيْرَة فَقَالَ لَا"],[267,"قلت فعمران بن حُصَيْن قَالَ اما فِي حَدِيث الْبَصرِيين فَلَا وَأما فِي حَدِيث الْكُوفِيّين فَنعم"],[268,"قلت فسمرة قَالَ لَا"],[269,"قلت فَابْن عَبَّاس قَالَ لَا"],[270,"وَسَأَلته عَن حسان بن إِبْرَاهِيم الْكرْمَانِي كَيفَ هُوَ قَالَ لَيْسَ بِهِ بَأْس"],[271,"قلت فَالْحكم بن عبد الْملك مَا حَاله فِي قَتَادَة فَقَالَ ضَعِيف"],[272,"فسعيد بن بشير فَقَالَ ضَعِيف"],[273,"قلت فحماد بن الْجَعْد فَقَالَ لَيْسَ بِشَيْء"],[274,"قلت فيونس بن عبيد أحب إِلَيْك فِي الْحسن أَو حميد فَقَالَ كِلَاهُمَا قَالَ أَبُو سعيد يُونُس أَكثر من حميد بِكَثِير"],[275,"قلت فحميد أحب إِلَيْك أَو حبيب بن الشَّهِيد فَقَالَ كِلَاهُمَا"],[276,"قلت فحشرج بن نباتة فَقَالَ ثِقَة"],[277,"فحاجب بن عمر فَقَالَ ثِقَة"],[278,"قلت فحاتم بن حُرَيْث الطَّائِي كَيفَ هُوَ فَقَالَ لَا اعرفه قَالَ أَبُو سعيد هُوَ شَامي ثِقَة"],[279,"قلت فالحسن بن عَيَّاش أَخُو أبي بكر بن عَيَّاش كَيفَ حَدِيثه فَقَالَ ثِقَة قلت هُوَ أحب إِلَيْك أَبُو بكر فَقَالَ هُوَ ثِقَة وَأَبُو بكر ثِقَة قَالَ أَبُو سعيد الْحسن وَأَبُو بكر ليسَا بِذَاكَ فِي الحَدِيث وهما من أهل الصدْق وَالْأَمَانَة"],[280,"قلت ليحيى فحمزة الزيات مَا حَاله فَقَالَ ثِقَة"],[281,"وَسَأَلته عَن الْحُسَيْن بن وَاقد فَقَالَ ثِقَة"],[282,"قَالَ أَبُو سعيد سمعته يَقُول الحكم بن مُوسَى ثِقَة"],[283,"والقواريري ثِقَة"],[284,"وَإِسْحَاق بن أبي إِسْرَائِيل ثِقَة قَالَ أَبُو سعيد لم يكن إِسْحَاق بن أبي إِسْرَائِيل أظهر الْوَقْف حِين سَأَلت يحيى عَنهُ وَهَذِه الْأَشْيَاء الَّتِي ظَهرت عَلَيْهِ بعد وَيَوْم كتبنَا عَنهُ كَانَ مَسْتُورا"],[285,"قلت ليحيى فعمرو بن دِينَار عَن بن أبي نجيح من أَبُو نجيح فَقَالَ هُوَ ثِقَة حَدثنَا عُثْمَان قَالَ"],[286,"سَأَلت يحيى بن معِين عَن خَالِد بن حَكِيم قَالَ هُوَ خَالِد بن حَكِيم بن حزَام ثِقَة"],[287,"وَسَأَلته عَن خَالِد بن الْحُوَيْرِث فَقَالَ لَا اعرفه"],[288,"وَسَأَلته عَن أبي خلدَة فَقَالَ ثِقَة"],[289,"قلت دَاوُد أحب إِلَيْك أم خَالِد الْحذاء فَقَالَ دَاوُد أحب الي"],[290,"قلت فَخَالِد بن إلْيَاس كَيفَ حَدِيثه فَقَالَ لَيْسَ بِشَيْء"],[291,"قلت فخليد بن دعْلج فَقَالَ ضَعِيف"],[292,"وَسَأَلته عَن خَالِد بن مخلد الْقَطوَانِي فَقَالَ لَيْسَ بِهِ بَأْس"],[293,"وَسَأَلته عَن خَلاد الصفار فَقَالَ لَيْسَ بِهِ بَأْس"],[294,"قلت فخطاب أعنى الْحَرَّانِي فَقَالَ هُوَ ثِقَة"],[295,"وَسَأَلته عَن خَالِد بن ذكْوَان فَقَالَ هُوَ ثِقَة"],[296,"قلت فَخَالِد بن يزِيد المكى مَا حَاله فَقَالَ لَا اعرفه"],[297,"وَسَأَلته عَن خلف بن تَمِيم أَي شَيْء حَاله فَقَالَ هُوَ الْمِسْكِين صَدُوق"],[298,"قلت يرْوى عَن عبد الله بن السرى من هُوَ قَالَ رجل"],[299,"قلت فَخَالِد بن قيس أَخُو نوح بن قيس فَقَالَ ثِقَة"],[300,"وَسَأَلته عَن خَارِجَة بن مُصعب فَقَالَ لَيْسَ بِشَيْء"],[301,"قلت فعبد الْكَرِيم أحب إِلَيْك أَو خصيف فَقَالَ عبد الْكَرِيم أحب الي وخصيف لَيْسَ بِهِ بَأْس حَدثنَا عُثْمَان قَالَ"],[302,"سَأَلت يحيى بن معِين عَن دَاوُد بن أبي هِنْد فَقَالَ ثِقَة"],[303,"وَسَأَلته عَن دَاوُد بن قيس الْفراء فَقَالَ ثِقَة"],[304,"وَسَأَلته عَن دَاوُد بن عبد الرَّحْمَن الْعَطَّار فَقَالَ ثِقَة"],[305,"قلت فداود بن خَالِد الْعَطَّار حَدثنَا عَنهُ يحيى يعْنى الْحمانِي فَقَالَ لَا اعرفه"],[306,"قلت فدراج أَبُو السَّمْح فَقَالَ ثِقَة قَالَ أَبُو سعيد دراج لَيْسَ بِذَاكَ وَهُوَ صَدُوق"],[307,"سَأَلت يحيى عَن دَيْلَم بن غَزوَان فَقَالَ ثِقَة"],[308,"وَسَأَلته عَن دَاوُد بن عَليّ عبد الله بن عَبَّاس فَقَالَ شيخ هاشمى قلت كَيفَ حَدِيثه فَقَالَ أَرْجُو انه لَيْسَ يكذب إِنَّمَا يحدث بِحَدِيث وَاحِد"],[309,"وَسَأَلته عَن دَاوُد بن فَرَاهِيجَ كَيفَ حَدِيثه فَقَالَ لَيْسَ بِهِ بَأْس"],[310,"قلت فداود الزعافرى من هُوَ فَقَالَ لَيْسَ بِشَيْء"],[311,"وَسَأَلته عَن دَاوُد بن أبي الْفُرَات مَا حَاله فَقَالَ ثِقَة"],[312,"قلت دَاوُد بن عَمْرو الَّذِي يروي عَنهُ هشيم مَا حَاله فَقَالَ ثِقَة"],[313,"قلت فداود بن الزبْرِقَان فَقَالَ لَيْسَ بِشَيْء حَدثنَا عُثْمَان قَالَ"],[314,"سَأَلت يحيى بن معِين عَن ذواد بن علبة مَا حَاله فَقَالَ ضَعِيف حَدثنَا عُثْمَان قَالَ"],[315,"سَأَلت يحيى بن معِين عَن رَبَاح بن عُبَيْدَة كَيفَ حَدِيثه فَقَالَ ثِقَة"],[316,"قلت فريحان بن يزِيد مَا حَاله فَقَالَ ثِقَة"],[317,"وَسَأَلته عَن رشيد الهجري فَقَالَ لَيْسَ برشيد وَلَا أَبوهُ"],[318,"قلت فرشدين بن سعد فَقَالَ لَيْسَ بِشَيْء"],[319,"قلت فراشد بن سعد فَقَالَ ثِقَة"],[320,"وَسَأَلته عَن الركين وَأَبِيهِ فَقَالَ ثقتان"],[321,"وَسَأَلته عَن رَاشد مولى حبيب بن أَوْس فَقَالَ ثِقَة يرْوى عَنهُ المصريون"],[322,"وَسَأَلته عَن رواد بن الْجراح الْعَسْقَلَانِي فَقَالَ ثِقَة"],[323,"قلت فَروح بن عبَادَة كَيفَ حَدِيثه فَقَالَ لَيْسَ بِهِ بَأْس"],[324,"قلت فربيعة بن كُلْثُوم فَقَالَ ثِقَة"],[325,"وَسَأَلته عَن الرّبيع بن صبيح فَقَالَ لَيْسَ بِهِ بَأْس وَكَأَنَّهُ لم يطره قلت هُوَ أحب إِلَيْك أَو الْمُبَارك فَقَالَ مَا أقربهما قَالَ أَبُو سعيد الْمُبَارك عِنْدِي فَوْقه فِيمَا سمع من الْحسن إِلَّا أَنه رُبمَا دلّس"],[326,"وَسَأَلته عَن الرّبيع بن فريع فَقَالَ ثِقَة حَدثنَا عُثْمَان قَالَ"],[327,"سَأَلت يحيى بن معِين عَن زيد بن جُبَير مَا حَاله فَقَالَ ثِقَة"],[328,"قلت فزياد بن جُبَير الَّذِي يروي عَن بن عمر فَقَالَ ثِقَة"],[329,"قلت وَزيد بن أبي أنيسَة مَا حَاله فَقَالَ ثِقَة"],[330,"قلت فزياد بن سعد أَي شَيْء حَاله فِي الزُّهْرِيّ فَقَالَ ثِقَة"],[331,"قلت فزكريا بن مَنْظُور كَيفَ حَدِيثه فَقَالَ لَيْسَ بِهِ بَأْس"],[332,"وَسَأَلته عَن زيد بن وَاقد كَيفَ هُوَ فَقَالَ ثِقَة"],[333,"قلت فزيد بن حباب فَقَالَ ثِقَة"],[334,"قلت من زُهَيْر أَبُو الْمُنْذر فَقَالَ لَيْسَ بِهِ بَأْس"],[335,"قلت فزهير بن مَرْزُوق تعرفه فَقَالَ لَا أعرفهُ"],[336,"قلت فزهير بن مُحَمَّد مَا حَاله فَقَالَ ثِقَة"],[337,"قلت فزياد بن مُسلم مَا حَاله فَقَالَ ثِقَة"],[338,"وَسَأَلته عَن زَكَرِيَّا أبي يحيى الْكُوفِي عَن الشّعبِيّ من زَكَرِيَّا هَذَا فَقَالَ لَيْسَ بِشَيْء قلت بن من هُوَ فَقَالَ بن يحيى"],[339,"وَسَأَلته عَن البكائي أَعنِي زيادا فَقَالَ لَا بَأْس بِهِ فِي الْمَغَازِي وَأما فِي غَيره فَلَا وَسَأَلت يحيى قلت عَمَّن أكتب الْمَغَازِي مِمَّن يروي عَن يُونُس أَو غَيره قَالَ اكتبه عَن أَصْحَاب البكائي"],[340,"قلت الزبير بن خريت مَا حَاله فَقَالَ لَيْسَ بِهِ بَأْس"],[341,"وَسَأَلته عَن زِيَاد بن مِخْرَاق كَيفَ حَدِيثه فَقَالَ ثِقَة حَدثنَا عُثْمَان قَالَ"],[342,"سَأَلت يحيى بن معِين عَن سعيد بن زيد بن عقبَة فَقَالَ ثِقَة"],[343,"وَسَأَلته عَن السَّائِب بن مَالك فَقَالَ ثِقَة قَالَ أَبُو سعيد وَقَالَ بَعضهم هُوَ أَبُو عَطاء بن السَّائِب وَقَالَ بَعضهم لَيْسَ هُوَ بِأَبِيهِ وَالصَّحِيح عَطاء بن السَّائِب بن زيد يكنى أَبَا زيد"],[344,"قلت سعيد بن عَامر الَّذِي يروي عَن بن عمر من هُوَ فَقَالَ لَيْسَ بِهِ بَأْس"],[345,"وَسَأَلته عَن سعيد بن زون فَقَالَ لَيْسَ بِشَيْء"],[346,"قلت فسلام بن مِسْكين فَقَالَ ثِقَة قلت فسلام أحب إِلَيْك فِي الْحسن أَو الْمُبَارك فَقَالَ سَلام"],[347,"وَسَأَلته عَن سكين بن عبد الْعَزِيز فَقَالَ ثِقَة"],[348,"قلت عِكْرِمَة أحب إِلَيْك عَن بن عَبَّاس أَو عبيد الله بن عبد الله فَقَالَ كِلَاهُمَا وَلم يُخَيّر قلت فعكرمة أَو سعيد بن جُبَير فَقَالَ ثِقَة وثقة وَلم يُخَيّر قَالَ أَبُو سعيد عبيد الله أجل من عِكْرِمَة"],[349,"قلت فسعيد أَو طَاوس فَقَالَ ثِقَات وَلم يُخَيّر"],[350,"وَسَأَلته قلت سمع بن الْمسيب من عمر فَقَالَ يَقُولُونَ لَا"],[351,"قلت لَهُ مَا حَال سُلَيْمَان بن مُوسَى فِي الزُّهْرِيّ فَقَالَ ثِقَة"],[352,"وَسَأَلته عَن سُلَيْمَان بن بُرَيْدَة كَيفَ حَدِيثه فَقَالَ ثِقَة"],[353,"قلت فسليمان الْأَحول فَقَالَ ثِقَة"],[354,"قلت فالقداح فَقَالَ ثِقَة"],[355,"قلت لَهُ فالزنجي فَقَالَ ثِقَة قَالَ عُثْمَان يُقَال فِي الزنْجِي والقداح ليسَا بِذَاكَ فِي الحَدِيث"],[356,"قلت فسعيد الْمُؤَذّن فَقَالَ لَا أعرفهُ"],[357,"قلت سعيد بن سِنَان أَبُو الْمهْدي فَقَالَ لَيْسَ بِشَيْء"],[358,"سَمِعت يحيى يَقُول سيف بن مُحَمَّد بن أُخْت سُفْيَان الثَّوْريّ كَانَ شَيخا هَا هُنَا كذابا خبيثا"],[359,"قلت فسعيد بن مسلمة الْأمَوِي فَقَالَ لَيْسَ بِشَيْء"],[360,"وَسَأَلته عَن سُوَيْد بن عَمْرو فَقَالَ ثِقَة"],[361,"وَسَأَلته عَن سُفْيَان بن عقبَة فَقَالَ لَا أعرفهُ"],[362,"وَسَأَلته عَن سعير بن الْخمس فَقَالَ ثِقَة"],[363,"قلت ليحيى بن معِين إِن بعض النَّاس يَقُولُونَ سُفْيَان بن عُيَيْنَة أثبت النَّاس فِي الزُّهْرِيّ فَقَالَ إِنَّمَا يَقُول ذَلِك من سمع مِنْهُ وَأي شَيْء كَانَ سُفْيَان إِنَّمَا كَانَ غليما قَالَ أَبُو سعيد يعْنى أَيَّام الزُّهْرِيّ"],[364,"وَسَأَلته عَن سعيد بن عُمَيْر بن عقبَة فَقَالَ لَا أعرفهُ"],[365,"قلت لَهُ سعيد بن زِيَاد الَّذِي يروي عَنهُ وَكِيع من هُوَ فَقَالَ ثِقَة"],[366,"سَمِعت يحيى فِي حَدِيث سُفْيَان عَن الْأَعْمَش عَن إِبْرَاهِيم عَن عَلْقَمَة مَا كَانَ فِي الْقُرْآن يَا أَيهَا النَّاس نزل بِمَكَّة فَقَالَ الصَّوَاب مَا قَالَ سُفْيَان قلت لَهُ الطنافسي أَعنِي يعلى يَقُول إِبْرَاهِيم عَن خَيْثَمَة فَقَالَ خطأ حَدثنَا عُثْمَان قَالَ قَالَ أَبُو خَيْثَمَة زُهَيْر بن حَرْب ليحيى فَكيف وَقفه حريز عَن إِبْرَاهِيم فَقَالَ لذا وَقع بخته"],[367,"قلت ليحيى فسلمى أَبُو بكر تعرفه يروي عَنهُ أَبُو أويس فَقَالَ هُوَ أَبُو بكر الْهُذلِيّ لَيْسَ بِشَيْء"],[368,"قلت فسعيد بن السَّائِب كَيفَ حَدِيثه فَقَالَ ثِقَة"],[369,"وَسَأَلته عَن سَالم أبي النَّضر فَقَالَ ثِقَة"],[370,"قلت فسالم بن أبي حَفْصَة فَقَالَ ثِقَة"],[371,"وَسَأَلته عَن سَالم الْخياط من هُوَ فَقَالَ لَيْسَ بِشَيْء"],[372,"قلت فسهل بن أبي أُمَامَة بن سهل فَقَالَ ثِقَة"],[373,"قلت فسالم بن أبي حَفْصَة فَقَالَ ثِقَة"],[374,"قلت فسهيل بن أبي صَالح أحب إِلَيْك عَن أَبِيه أَو سمي عَنهُ فَقَالَ سمي خير مِنْهُ"],[375,"وَسَأَلته عَن سعيد بن مُسلم بن بانك فَقَالَ ثِقَة"],[376,"وَسَأَلته عَن سُلَيْمَان بن سُفْيَان تعرفه فَقَالَ لَا أعرفهُ"],[377,"قلت فسليمان بن دَاوُد الَّذِي يروي حَدِيث الزُّهْرِيّ فِي الصَّدقَات من هُوَ فَقَالَ لَيْسَ بِشَيْء قَالَ أَبُو سعيد أَرْجُو أَنه لَيْسَ كَمَا قَالَ يحيى وَقد روى عَنهُ يحيى بن حَمْزَة أَحَادِيث حسانا كلهَا مُسْتَقِيمَة وَهُوَ دمشقي خولاني"],[378,"سَأَلت يحيى عَن سُبْرَة بن عبد الْعَزِيز فَقَالَ لَيْسَ بِهِ بَأْس"],[379,"قلت فسعيد بن عبد الرَّحْمَن الجُمَحِي كَيفَ حَدِيثه فَقَالَ ثِقَة"],[380,"قلت فسليمان بن بِلَال أحب إِلَيْك أَو الدَّرَاورْدِي فَقَالَ سُلَيْمَان وَكِلَاهُمَا ثِقَة"],[381,"قلت والسالحيني أَي شَيْء حَاله فَقَالَ صَدُوق الْمِسْكِين قَالَ أَبُو سعيد اسْمه يحيى بن إِسْحَاق يروي عَنهُ أَبُو بكر وَعُثْمَان أَبنَاء أبي شيبَة"],[382,"وَسَأَلته عَن سهل بن حَمَّاد فَقَالَ من سهل قلت هَذَا الَّذِي مَاتَ قَرِيبا الْأَزْدِيّ حَدثنَا عَنهُ أَبُو مُسلم وَغَيره فَقَالَ مَا أعرفهُ قَالَ أَبُو سعيد هُوَ صَاحب أبي عوَانَة لَا بَأْس بِهِ"],[383,"وَسَأَلته عَن سُفْيَان بن هِشَام الْمروزِي تعرفه فَقَالَ لَا قلت حَدثنَا عَنهُ الْهَيْثَم بن خَارِجَة بِأَحَادِيث عَن بن بُرَيْدَة يُقَال لَهُ أَبُو مُجَاهِد فَقَالَ مَا أعرفهُ"],[384,"وَسَأَلت يحيى عَن سعيد التمار عَن أنس من هُوَ فَقَالَ لَا أَدْرِي"],[385,"قلت مَا حَال سعيد بن زَرْبِي فَقَالَ لَيْسَ بِشَيْء"],[386,"قلت فسعيد بن عَامر فَقَالَ ثِقَة"],[387,"قلت فسليم بن أَخْضَر كَيفَ هُوَ فَقَالَ ثِقَة"],[388,"قلت فسلمة بن وردان كَيفَ حَدِيثه فَقَالَ لَيْسَ بِشَيْء"],[389,"قلت فَسلم بن أبي الذَّيَّال فَقَالَ ثِقَة قلت رُوِيَ عَنهُ غير الْمُعْتَمِر فَقَالَ نعم هُوَ مَشْهُور ثِقَة"],[390,"قلت فسويد أَبُو حَاتِم مَا حَاله فِي قَتَادَة فَقَالَ أَرْجُو أَن لَا يكون بِهِ بَأْس"],[391,"قلت فسعيد بن بشير فَقَالَ ضَعِيف"],[392,"قلت فسليمان بن أَرقم فَقَالَ لَيْسَ بِشَيْء"],[393,"وَسَأَلته عَن سَلمَة بن نمام كَيفَ حَدِيثه فَقَالَ ثِقَة"],[394,"قلت فسفيان بن دِينَار كَيفَ حَدِيثه فَقَالَ هُوَ ثِقَة"],[395,"وَسَأَلته عَن سعيد أبي الصَّباح فَقَالَ لَا أعرفهُ"],[396,"وَسَأَلته عَن سُلَيْمَان بن قرم فَقَالَ لَيْسَ بِشَيْء"],[397,"قلت فسراج بن عقبَة فَقَالَ لَيْسَ بِهِ بَأْس ثِقَة"],[398,"قلت فَأَبُو الْهَيْثَم الَّذِي روى عَنهُ دراج فَقَالَ ثِقَة"],[399,"قلت فسليمان بن حبيب فَقَالَ ثِقَة"],[400,"وَسَأَلته عَن سوَاده بن حَيَّان كَيفَ حَدِيثه فَقَالَ ثِقَة"],[401,"قلت فَكيف حَدِيث سُلَيْمَان بن حَيَّان فَقَالَ ثِقَة حَدثنَا عُثْمَان قَالَ"],[402,"سَأَلت يحيى عَن شُعَيْب بن رُزَيْق الطَّائِفِي من هُوَ فَقَالَ لَيْسَ بِهِ بَأْس"],[403,"وَسَأَلت يحيى قلت لَهُ شييم بن بيتان مَا حَاله فَقَالَ ثِقَة"],[404,"وَسَأَلته عَن شهَاب بن خرَاش فَقَالَ لَيْسَ بِهِ بَأْس"],[405,"حَدثنَا عُثْمَان سَمِعت يَعْقُوب بن إِبْرَاهِيم الدَّوْرَقِي يَقُول قَالَ عبد الرَّحْمَن يعْنى بن مهْدي لَيْسَ أحد أصح حَدِيثا عَن أبي إِسْحَاق من شُعْبَة"],[406,"حَدثنَا عُثْمَان قَالَ سَأَلت يحيى عَن شَاذان فَقَالَ لَا بَأْس بِهِ"],[407,"قلت هُوَ أحب إِلَيْك أم شَبابَة فَقَالَ شَبابَة أحب إِلَيّ"],[408,"وَسَأَلته عَن شمر بن عَطِيَّة فَقَالَ ثِقَة"],[409,"قلت فشميسة تِلْكَ فَقَالَ ثِقَة"],[410,"وَسَأَلته عَن شُعَيْب بن طَلْحَة كَيفَ هُوَ فَقَالَ لَا أعرفهُ"],[411,"قلت فشريك بن عبد الله بن أبي نمر كَيفَ حَدِيثه فَقَالَ لَيْسَ بِهِ بَأْس"],[412,"قلت فيحيى بن حَمْزَة عَن شَدَّاد بن مُحَمَّد من شَدَّاد فَقَالَ شيخ لَهُم ثِقَة"],[413,"وَسَأَلته عَن شُعَيْب بن حَرْب مَا حَاله فَقَالَ ثِقَة"],[414,"قلت فشعيب بن إِسْحَاق كَيفَ حَدِيثه فَقَالَ ثِقَة"],[415,"قلت فشعبة الْكُوفِي فَقَالَ ثِقَة"],[416,"وَسَأَلت يحيى قلت شُعْبَة أحب إِلَيْك فِي قَتَادَة أَو هِشَام فَقَالَ كِلَاهُمَا قَالَ عُثْمَان هِشَام فِي قَتَادَة أَكثر من شُعْبَة"],[417,"وَسمعت يحيى يَقُول شُعَيْب بن أبي حَمْزَة كتب عَن الزُّهْرِيّ إملاء للسُّلْطَان كَانَ كَاتبا"],[418,"قلت فَأَبُو عمار الَّذِي يروي عَنهُ الْأَوْزَاعِيّ مَا حَاله قَالَ شَدَّاد لَيْسَ بِهِ بَأْس حَدثنَا عُثْمَان قَالَ"],[419,"سَأَلت يحيى عَن صَدَقَة بن عبد الله السمين فَقَالَ ضَعِيف"],[420,"وَسَأَلته عَن صَدَقَة بن خَالِد فَقَالَ ثِقَة"],[421,"وَسَأَلته عَن صَالح بن جُبَير كَيفَ هُوَ قَالَ ثِقَة"],[422,"وَسَأَلته عَن الصَّلْت بن بهْرَام كَيفَ هُوَ فَقَالَ ثِقَة"],[423,"قلت فالصلت بن دِينَار فَقَالَ لَيْسَ بِشَيْء"],[424,"قلت فالصعق بن حزن كَيفَ هُوَ فَقَالَ ثِقَة"],[425,"قلت لَهُ فَمَا حَال صَالح بن حَيَّان فَقَالَ ضَعِيف"],[426,"وَسَأَلته عَن صَالح مولى التَّوْأَمَة كَيفَ حَدِيثه فَقَالَ ثِقَة"],[427,"قلت فَصَالح بن مهْرَان مولى عَمْرو بن حُرَيْث فَقَالَ ضَعِيف"],[428,"وَسَأَلته عَن صَالح بن حسان فَقَالَ لَيْسَ بِشَيْء"],[429,"قلت فالصباح أَبُو سهل الوَاسِطِيّ تعرفه فَقَالَ لَا أعرفهُ حَدثنَا عُثْمَان قَالَ"],[430,"سَأَلت يحيى بن معِين عَن ضَمْضَم بن جوس فَقَالَ ثِقَة"],[431,"وَسَأَلته عَن ضَمرَة بن حبيب فَقَالَ ثِقَة"],[432,"وَسَأَلته عَن ضَمرَة بن ربيعَة فَقَالَ ثِقَة"],[433,"قلت فالضحاك بن عُثْمَان كَيفَ حَدِيثه فَقَالَ ثِقَة"],[434,"وَسَأَلته عَن ضَمْضَم بن زرْعَة فَقَالَ ثِقَة"],[435,"قلت وَأَبُو عَاصِم أَعنِي النَّبِيل فَقَالَ ثِقَة حَدثنَا عُثْمَان قَالَ"],[436,"سَأَلت يحيى عَن طعمة بن عَمْرو فَقَالَ ثِقَة"],[437,"وَسَأَلته عَن طَلْحَة بن يحيى فَقَالَ ثِقَة"],[438,"وَسَأَلته عَن طَلْحَة بن جبر كَيفَ هُوَ فَقَالَ ثِقَة حَدثنَا عُثْمَان قَالَ"],[439,"سَأَلت يحيى عَن أبي عَامر الْعَقدي فَقَالَ ثِقَة"],[440,"وَسَأَلته عَن عَمْرو بن دِينَار قهرمان آل الزبير فَقَالَ لَيْسَ بِشَيْء"],[441,"وَسَأَلته عَن عبد الرَّحْمَن بن الغسيل فَقَالَ صُوَيْلِح"],[442,"وَسَأَلته عَن عَاصِم بن عبيد الله فَقَالَ ضَعِيف"],[443,"وَسَأَلته عَن عبد الله بن مُبشر فَقَالَ ثِقَة"],[444,"قلت يروي عَن زيد أبي عتاب فَقَالَ ثِقَة"],[445,"قلت والْعَلَاء بن صَالح فَقَالَ لَا بَأْس بِهِ"],[446,"قلت عبد الْجَبَّار بن وَائِل كَيفَ هُوَ فَقَالَ لَا بَأْس بِهِ"],[447,"وَسَأَلته عَن عَمْرو بن يحيى أَعنِي الْمَازِني فَقَالَ صُوَيْلِح وَلَيْسَ بِالْقَوِيّ"],[448,"وَسَأَلته عَن عبيد الله بن عبد الله أبي الْمُنِيب الْعَتكِي فَقَالَ ثِقَة"],[449,"قلت فعثمان بن حَكِيم فَقَالَ ثِقَة"],[450,"وَسَأَلته عَن عبد الرَّحْمَن بن العداء فَقَالَ ثِقَة"],[451,"قلت وَالْعَبَّاس بن سهل فَقَالَ السَّاعِدِيّ ثِقَة"],[452,"قلت فَأَبُو عقيل عبد الله بن عقيل الثَّقَفِيّ كَيفَ هُوَ فَقَالَ ثِقَة لَا بَأْس بِهِ"],[453,"قلت فعمر بن عبد الله بن يعلى الَّذِي يروي عَنهُ إِسْرَائِيل مَا حَاله فَقَالَ لَيْسَ بِشَيْء"],[454,"قلت فعثمان بن حَكِيم عَن عبد الرَّحْمَن بن عبد الْعَزِيز من هَذَا فَقَالَ شيخ مَجْهُول"],[455,"فَقلت فعبد الله بن حَفْص الَّذِي يروي عَنهُ قَالَ شيخ لَا أعرفهُ"],[456,"وَسَأَلته عَن عمر بن مُوسَى الْأنْصَارِيّ فَقَالَ لَا بَأْس بِهِ"],[457,"وَعَن أَبِيه مُوسَى فَقَالَ ثِقَة لَا بَأْس بِهِ"],[458,"وَسَأَلته عَن عبيد الله بن الْأَخْنَس فَقَالَ ثِقَة"],[459,"وَسَأَلته عَن الْوَلِيد بن عبد الله فَقَالَ ثِقَة"],[460,"قلت وَابْن أبي نجيح عَن عبيد الله بن عَامر عَن عبد الله بن عَمْرو من عبيد الله فَقَالَ هُوَ ثِقَة"],[461,"قلت فعمرو بن دِينَار عَن أبي الْعَبَّاس من أَبُو الْعَبَّاس فَقَالَ هُوَ مَشْهُور قلت هُوَ الَّذِي يروي عَنهُ حبيب بن أبي ثَابت فَقَالَ نعم"],[462,"وَسَأَلته عَن عبد الْوَاحِد بن قيس فَقَالَ ثِقَة"],[463,"وَسَأَلته عَن عَليّ بن زيد بن جدعَان فَقَالَ لَيْسَ بِذَاكَ الْقوي"],[464,"وَسَأَلته عَن عبد الله بن عبد الرَّحْمَن بن يعلى الطَّائِفِي فَقَالَ صُوَيْلِح"],[465,"وَسَأَلته عَن الأفريقي أَعنِي عبد الرَّحْمَن فَقَالَ ضَعِيف"],[466,"وَسَأَلته عَن عمرَان بن عبد الله فَقَالَ ضَعِيف"],[467,"وَسَأَلته عَن عبد الله بن المؤمل فَقَالَ ضَعِيف"],[468,"قلت فعبد الله بن يزِيد عَن عبد الله بن عَمْرو فَقَالَ ثِقَة قَالَ أَبُو سعيد هُوَ أَبُو عبد الرَّحْمَن الحبلي"],[469,"قلت مَا حَال عمر بن حَمْزَة الَّذِي يروي عَن سَالم فَقَالَ ضَعِيف"],[470,"قلت الْعَلَاء بن عبد الْكَرِيم فَقَالَ ثِقَة"],[471,"وَسَأَلته عَن عبد الله بن سعيد بن أبي هِنْد فَقَالَ ثِقَة"],[472,"وَسَأَلته عَن عبد الرَّحْمَن بن عبد الله الغافقي فَقَالَ لَا أعرفهُ"],[473,"وَسَأَلته عَن عَن عبد الله بن أبي لبيد فَقَالَ ثِقَة"],[474,"وَسَأَلته عَن أبي حَفْص الْأَبَّار كَيفَ هُوَ فَقَالَ ثِقَة"],[475,"وَسَأَلته عَن عبَادَة بن مُسلم الْفَزارِيّ فَقَالَ ثِقَة"],[476,"قلت عبد الله بن أبي سُلَيْمَان أحب إِلَيْك أوابن جريج فَقَالَ كِلَاهُمَا ثقتان"],[477,"قلت فعبد الله بن نعْمَان عَن قيس بن طلق قَالَ شُيُوخ يمامية ثِقَات"],[478,"قلت فعبد الله بن بدر فَقَالَ ثِقَة"],[479,"قلت فعجيبة بن عبد الحميد فَقَالَ ثِقَة"],[480,"قلت أَيُّوب بن عتبَة أحب إِلَيْك أَو عِكْرِمَة بن عمار فَقَالَ عِكْرِمَة أحب إِلَيّ أَيُّوب ضَعِيف"],[481,"وَسَأَلته عَن عَليّ بن يحيى بن خَلاد فَقَالَ ثِقَة"],[482,"وَسَأَلته عَن عَمْرو بن مَيْمُون الْجَزرِي فَقَالَ ثِقَة"],[483,"قلت فعبد الْكَرِيم أحب إِلَيْك أَو خصيف قَالَ عبد الْكَرِيم أحب إِلَيّ وخصيف لَيْسَ بِهِ بَأْس"],[484,"قلت فعبيد الله أعنى بن عَمْرو الرقي فَقَالَ ثِقَة"],[485,"وَسَأَلته عَن عباد بن كثير الرَّمْلِيّ فَقَالَ ثِقَة"],[486,"قلت فَعبَّاد بن عباد فَقَالَ عباد الْخَواص الَّذِي كَانَ ينزل الرملة ثِقَة"],[487,"وَعباد بن كثير الَّذِي كَانَ يكون بِمَكَّة لَيْسَ بِشَيْء فِي الحَدِيث وَكَانَ رجلا صَالحا"],[488,"وَعباد بن عباد المهلبي ثِقَة"],[489,"وَسَأَلته عَن عبد الرَّحْمَن بن ثَابت بن ثَوْبَان فَقَالَ عبد الرَّحْمَن ضَعِيف وَأَبوهُ ثِقَة"],[490,"وَسَأَلته عَن عَطاء الْخُرَاسَانِي فَقَالَ ثِقَة"],[491,"وَسَأَلته عَن عَليّ بن الْمُبَارك فَقَالَ ثِقَة"],[492,"وَسَأَلته عَن عمَارَة بن زَاذَان فَقَالَ ثِقَة"],[493,"وَسَأَلته عَن عزْرَة بن ثَابت فَقَالَ ثِقَة"],[494,"قلت فعلي بن عَليّ الرِّفَاعِي فَقَالَ ثِقَة"],[495,"وَسَأَلته عَن عبد الْعَزِيز بن قرير فَقَالَ ثِقَة"],[496,"وَسَأَلته عَن عون بن مُوسَى فَقَالَ ثِقَة"],[497,"وَسَأَلته عَن عبد الْوَاحِد بن زيد فَقَالَ لَيْسَ بِشَيْء"],[498,"وَسَأَلته عَن عمر بن الْوَلِيد الشني فَقَالَ ثِقَة"],[499,"وَسَأَلته عَن الْعَوام بن حَوْشَب فَقَالَ ثِقَة"],[500,"وَسَأَلته عَن عِكْرِمَة بن إِبْرَاهِيم الْأَزْدِيّ فَقَالَ لَيْسَ بِشَيْء"],[501,"قلت فعبيدة بن رائطة فَقَالَ لَيْسَ بِهِ بَأْس"],[502,"قلت فعاصم بن مُحَمَّد كَيفَ حَدِيثه فَقَالَ ثِقَة"],[503,"قلت فعبيد الله بن إياد بن لَقِيط فَقَالَ ثِقَة"],[504,"قلت فعلقمة أحب إِلَيْك عَن عبد الله أَو عُبَيْدَة فَلم يُخَيّر"],[505,"قَالَ أَبُو سعيد كِلَاهُمَا ثقتان وعلقمه أعلم بِعَبْد الله"],[506,"قلت فَأَبُو عُبَيْدَة عَن عبد الله فَقَالَ ثِقَة وَلم يسمع من عبد الله"],[507,"قلت فعاصم بن ضَمرَة فَقَالَ ثِقَة"],[508,"قلت فعبد خير فَقَالَ ثِقَة"],[509,"قلت لَهُ وَعَاصِم أحب إِلَيْك أم حَارِثَة أَعنِي بن مضرب فَقَالَ كِلَاهُمَا وَلم يُخَيّر قَالَ أَبُو سعيد حَارِثَة خير"],[510,"وَسَأَلته عَن عبد الْوَهَّاب بن عَطاء الْخفاف فَقَالَ لَيْسَ بِهِ بَأْس"],[511,"وَسَأَلته عَن عَمْرو بن ثَابت فَقَالَ كُوفِي لَيْسَ بِشَيْء"],[512,"قلت لَهُ نَافِع أحب عَن بن عمر أَو سَالم فَلم يفضل"],[513,"قلت فنافع أَو عبد الله بن دِينَار فَقَالَ ثِقَات وَلم يفضل"],[514,"قلت ليحيى عبد الله الْعمريّ مَا حَاله فِي نَافِع فَقَالَ صَالح"],[515,"قلت فالليث أَعنِي بن سعد كَيفَ حَدِيثه عَن نَافِع فَقَالَ صَالح ثِقَة"],[516,"فمالك أحب إِلَيْك عَن نَافِع أَو عبيد الله فَقَالَ كِلَاهُمَا وَلم يفضل"],[517,"وَسَأَلته عَن عمَارَة بن أبي حَفْصَة فَقَالَ ثِقَة"],[518,"قلت لَهُ فعبد الرَّحْمَن بن زيد بن أسلم كَيفَ حَدِيثه فَقَالَ ضَعِيف"],[519,"قلت فعبد الله بن زيد فَقَالَ ضَعِيف"],[520,"قلت فعبد الرَّحْمَن بن أبي الزِّنَاد فَقَالَ ضَعِيف"],[521,"قلت فأسامة بن زيد الصَّغِير أَعنِي بن أسلم فَقَالَ ضَعِيف"],[522,"قلت كَيفَ حَدِيث أبي عَلْقَمَة الْفَروِي فَقَالَ ثِقَة"],[523,"قلت فعبد الله بن نَافِع الصَّائِغ فَقَالَ ثِقَة"],[524,"قلت كَيفَ رِوَايَة بن لَهِيعَة عَن أبي الزبير عَن جَابر فَقَالَ بن لَهِيعَة ضَعِيف الحَدِيث"],[525,"قلت فعبد الله بن الْعَلَاء بن زبر فَقَالَ ثِقَة"],[526,"حَدثنَا عُثْمَان قَالَ سَأَلت دحيما عَن عبد الله بن بن الْعَلَاء بن زبر فوثقه جدا"],[527,"قلت ليحيى بن معِين فعفير بن معدان فَقَالَ لَيْسَ بِشَيْء"],[528,"قلت فعثمان بن كثير بن دِينَار كَيفَ هُوَ فَقَالَ ثِقَة"],[529,"قلت فعطاء بن مُسلم كَيفَ هُوَ فَقَالَ ثِقَة"],[530,"قلت فعتاب بن بشير فَقَالَ ثِقَة قَالَ أَبُو سعيد وَهُوَ من أهل حران"],[531,"حَدثنَا عُثْمَان قَالَ سَمِعت عَليّ بن الْمَدِينِيّ يَقُول ضربنا على حَدِيث عتاب بن بشير"],[532,"سَأَلت يحيى عَن السَّهْمِي أعنى عبد الله بن بكر فَقَالَ ثِقَة"],[533,"قلت فعبيدة بن حميد قَالَ مَا بِهِ مِسْكين بَأْس لَيْسَ لَهُ بخت"],[534,"وَسَأَلته عَن يعلى وَمُحَمّد ابْني عبيد الطنافسيين فَقَالَ ثقتان"],[535,"قلت فعمر أَعنِي بن عبيد فَقَالَ ثِقَة قلت كَأَنَّهُ دونهمَا فَقَالَ نعم"],[536,"وَسَأَلته عَن أبي خَالِد الْأَحْمَر فَقَالَ لَيْسَ بِهِ بَأْس"],[537,"قلت وَأَبُو خَالِد أحب إِلَيْك أَو عَليّ بن مسْهر فَقَالَ عَليّ بن مسْهر أحب إِلَيّ"],[538,"قلت فإسحاق الْأَزْرَق فَقَالَ ثِقَة"],[539,"قلت إِسْحَاق أحب إِلَيْك أَو بن مسْهر فَقَالَ بن مسْهر أحب إِلَيّ"],[540,"قلت فَابْن مسْهر أحب إِلَيْك أَو يحيى بن زَكَرِيَّا فَقَالَ كِلَاهُمَا ثقتان"],[541,"وَسَأَلته عَن عبد السَّلَام بن حَرْب فَقَالَ هُوَ صَدُوق"],[542,"وَسَأَلته عَن مُحَمَّد بن فُضَيْل فَقَالَ ثِقَة"],[543,"قلت عبد السَّلَام أحب إِلَيْك أَو مُحَمَّد بن فُضَيْل فَقَالَ مُحَمَّد أحب إِلَيّ"],[544,"وَسَأَلته عَن عَمْرو بن طَلْحَة فَقَالَ ذَاك القناد صَدُوق"],[545,"قلت فعبيد الله بن الْوَلِيد الْوَصَّافِي فَقَالَ لَيْسَ بِشَيْء"],[546,"سَمِعت يحيى بن معِين يَقُول عبد الله بن مُحَمَّد لَيْسَ بِثِقَة"],[547,"قلت وَأَبُو سعيد الْمُؤَدب أَعنِي مولى بني هَاشم فَقَالَ ثِقَة"],[548,"قلت وَأَبُو إِسْمَاعِيل الْمُؤَدب مَا حَاله فَقَالَ ثِقَة"],[549,"وَسَأَلته عَن عُثْمَان أبي الْيَقظَان فَقَالَ لَيْسَ بِهِ بَأْس"],[550,"قلت فعبد الرَّحْمَن بن أبي زِيَاد الَّذِي يرْوى عَنهُ الْأَعْمَش فَقَالَ ثِقَة"],[551,"قلت مَا حَال لَيْث بن أبي سليم فَقَالَ ضَعِيف"],[552,"قلت يروي عَن عُمَيْر بن أبي عُمَيْر فَقَالَ لَا أعرفهُ"],[553,"وَسَأَلته عَن عبد الْكَرِيم بن سليط من هُوَ فَقَالَ لم يرو عَنهُ إِلَّا الْحسن بن صَالح"],[554,"وَسَأَلته عَن عمار بن رُزَيْق فَقَالَ ثِقَة"],[555,"وَسَأَلته عَن عبد الله بن بشر فَقَالَ ثِقَة قَالَ عُثْمَان هُوَ الَّذِي يروي عَنهُ عبد السَّلَام بن حَرْب يروي عَن الزُّهْرِيّ لَيْسَ بِذَاكَ"],[556,"وَسَأَلته عَن عبد الله بن عِيسَى فَقَالَ ثِقَة"],[557,"وَسَأَلته عَن عِيسَى بن عبد الرَّحْمَن بن أبي ليلى فَقَالَ ثِقَة"],[558,"وَسَأَلته عَن عبد الله بن يسَار الَّذِي يروي عَنهُ مَنْصُور عَن حُذَيْفَة لَا تَقولُوا مَا شَاءَ الله وَشاء فلَان ألقِي حُذَيْفَة فَقَالَ لَا أعلمهُ"],[559,"وسمعته يَقُول عَمْرو بن خَالِد الَّذِي يرْوى عَنهُ أَبُو حَفْص الْأَبَّار شيخ كُوفِي كَذَّاب يرْوى عَن زيد بن عَليّ عَن ابائه عَن عَليّ"],[560,"وسمعته يَقُول عبد الْعَزِيز بن أبان الْقرشِي لَيْسَ بِثِقَة قلت من أَيْن جَاءَ ضعفه فَقَالَ كَانَ يَأْخُذ أَحَادِيث النَّاس فيرويها"],[561,"قلت فعبد الله بن الْوَلِيد الْعَدنِي فَقَالَ لَا أعرفهُ وَلم أكتب عَنهُ شَيْئا"],[562,"وسمعته يَقُول عبد الله بن عصم هُوَ أَبُو علوان وَبَعْضهمْ يَقُول بن عصمَة"],[563,"وَسَأَلته عَن عَاصِم الْأَحول كَيفَ حَدِيثه فَقَالَ ثِقَة"],[564,"قلت فعامر الْأَحول فَقَالَ لَيْسَ بِهِ بَأْس"],[565,"قلت لَهُ فعبد الله بن الْقَاسِم الَّذِي يروي عَنهُ بن شَوْذَب كَيفَ هُوَ فَقَالَ لَيْسَ بِهِ بَأْس"],[566,"قلت فالعلاء أَبُو مُحَمَّد النَّهْدِيّ فَقَالَ الْعَلَاء ثِقَة مَشْهُور"],[567,"قلت فعمير بن إِسْحَاق كَيفَ حَدِيثه فَقَالَ ثِقَة"],[568,"وَسَأَلته عَن عبد الحميد بن الْحسن الْهِلَالِي فَقَالَ ثِقَة"],[569,"وَسَأَلته عَن عدي بن الْفضل كَيفَ حَدِيثه فَقَالَ لَيْسَ بِثِقَة"],[570,"قلت يروي عَن أبي جَعْفَر الْمدنِي من أَبُو جَعْفَر هَذَا فَقَالَ أرَاهُ الخطمي"],[571,"وَسَأَلته عَن عِكْرِمَة بن خَالِد فَقَالَ ثِقَة"],[572,"قلت هُوَ أصح حَدِيثا أَو عِكْرِمَة مولى بن عَبَّاس فَقَالَ كِلَاهُمَا ثقتان"],[573,"قلت فعبد الرَّحْمَن بن سعد الْمدنِي الَّذِي يروي عَنهُ بن وهب مَا حَاله فَقَالَ لَا أعرفهُ"],[574,"قلت فعبد الرَّحْمَن بن عبد الله بن الْأَصَم كَيفَ هُوَ فَقَالَ ثِقَة"],[575,"قلت فالعلاء بن أبي الْعَبَّاس فَقَالَ ثِقَة"],[576,"قلت فعمارة بن غزيَّة كَيفَ هُوَ فَقَالَ لَيْسَ بِهِ بَأْس"],[577,"وَسُئِلَ عَن عبد الرَّحْمَن بن الْحَارِث بن أبي ربيعَة كَيفَ هُوَ فَقَالَ لَيْسَ بِهِ بَأْس"],[578,"قلت فعبد الْحَكِيم بن أبي فَرْوَة فَقَالَ ثِقَة"],[579,"وَسَأَلته عَن عبد الله بن جَعْفَر بن الْمسور فَقَالَ ثِقَة"],[580,"قلت فعبد الله بن الْحَارِث بن فُضَيْل الخطمي فَقَالَ ثِقَة"],[581,"قلت فأبوه فَقَالَ ثِقَة"],[582,"قلت فعبد الله بن عبد الرَّحْمَن الجُمَحِي كَيفَ حَدِيثه عَن بن شهَاب فَقَالَ لَا أعرفهُ"],[583,"قلت فعاصم بن سُوَيْد الْأنْصَارِيّ فَقَالَ لَا أعرفهُ"],[584,"قلت فعبد الله بن سُلَيْمَان الَّذِي يروي عَن معَاذ بن عبد الله بن خبيب فَقَالَ ثِقَة"],[585,"وَسَأَلته عَن عبد الْوَاحِد بن حَمْزَة فَقَالَ لَيْسَ بِهِ بَأْس"],[586,"قلت فعبد الله بن سعيد المَقْبُري فَقَالَ لَيْسَ بِشَيْء"],[587,"قلت فعقبة بن بشير فَقَالَ مَا أعرفهُ"],[588,"فعمر بن عُثْمَان الَّذِي روى عَن أَبِيه عَن بن شهَاب مَا حَالهمَا فَقَالَ مَا أَعْرفهُمَا"],[589,"قلت فَمن عبد الله الْبنانِيّ الَّذِي يروي عَنهُ معن فَقَالَ مَا أعرفهُ"],[590,"قلت فعنبسة بن مهْرَان عَن الزُّهْرِيّ من عَنْبَسَة يروي عَنهُ يحيى بن المتَوَكل فَقَالَ لَا أعرفهُ"],[591,"قلت فعبد الرَّحْمَن بن آدم كَيفَ هُوَ فَقَالَ لَا أعرفهُ"],[592,"قلت فعبد الله بن عبد الرَّحْمَن الطَّائِفِي مَا حَاله فَقَالَ ضَعِيف"],[593,"قلت فعائذ بن بشير كَيفَ حَدِيثه فَقَالَ ضَعِيف"],[594,"وَسَأَلته عَن عبد الرَّحْمَن بن مُعَاوِيَة الَّذِي يروي عَن بن أبي ذُبَاب فَقَالَ هُوَ أَبُو الْحُوَيْرِث ثِقَة"],[595,"قلت ليحيى كريب أحب إِلَيْك عَن بن عَبَّاس أَو عِكْرِمَة فَقَالَ كِلَاهُمَا ثِقَة"],[596,"قلت فعياية بن رِفَاعَة مَا حَاله فَقَالَ ثِقَة"],[597,"قلت فعبد الله بن مُحَمَّد بن عمار بن سعد وعمار وَعمر ابنى حَفْص بن عمر بن سعد عَن أبائهم عَن أجدادهم كَيفَ حَال هَؤُلَاءِ فَقَالَ لَيْسُوا بِشَيْء"],[598,"قلت فَابْن أبي ثَابت عبد الْعَزِيز بن عمرَان من ولد عبد الرَّحْمَن بن عَوْف مَا حَاله فَقَالَ لَيْسَ بِثِقَة وَإِنَّمَا كَانَ صَاحب شعر"],[599,"قلت فعبد الله بن عُثْمَان بن سعد بن إِسْحَاق يروي حَدِيث أبي أسيد فِي الْغلُول كَيفَ هُوَ فَقَالَ لَا أعرفهُ"],[600,"قلت فعثمان بن عمر بن عُثْمَان بن سُلَيْمَان بن أبي حثْمَة كَيفَ حَاله فَقَالَ لَا أعرفهُ"],[601,"قلت فَكيف حَدِيث عبد الحميد بن جَعْفَر فَقَالَ هُوَ ثِقَة"],[602,"قلت فعاصم بن عمر بن قَتَادَة فَقَالَ صَدُوق"],[603,"وَسَأَلته عَن عبد الله بن مُحَمَّد الْفَروِي فَقَالَ صَدُوق"],[604,"قلت مُعَاوِيَة بن إِسْحَاق كَيفَ حَدِيثه فَقَالَ هُوَ ثِقَة"],[605,"وَسَأَلته عَن عُثْمَان بن وَاقد الْعمريّ فَقَالَ لَيْسَ بِهِ بَأْس"],[606,"قلت فأبوه أرَاهُ قَالَ ثِقَة"],[607,"وَسَأَلته عَن عطاف بن خَالِد فَقَالَ ثِقَة"],[608,"قلت عَن أمه كَيفَ حَدِيثهَا فَقَالَ ثِقَة"],[609,"وَسَأَلته عَن يحيى بن زبان فَقَالَ لَا أعرفهُ"],[610,"قلت فعبد الْأَعْلَى الزُّهْرِيّ عَن زِيَاد بن علاقَة تعرفه فَقَالَ لَا أعرفهُ"],[611,"قلت وَإِسْمَاعِيل بن سميع فَقَالَ ثِقَة"],[612,"قلت عَن عَليّ بن كثير من عَليّ فَقَالَ ثِقَة"],[613,"قلت على بن عُرْوَة عَن مُحَمَّد بن الْمُنْكَدر مَا حَال عَليّ فَقَالَ لَيْسَ بِشَيْء"],[614,"وَسَأَلته عَن الْعَلَاء بن عبد الرَّحْمَن عَن أَبِيه كَيفَ حَدِيثهمَا فَقَالَ لَيْسَ بِهِ بَأْس"],[615,"قلت هُوَ أحب إِلَيْك أَو سعيد المَقْبُري فَقَالَ سعيد أوثق والْعَلَاء ضَعِيف"],[616,"قلت فعياش بن عَبَّاس فَقَالَ ثِقَة"],[617,"قلت فعبيد الله بن زحر كَيفَ حَدِيثه فَقَالَ كل حَدِيثه عِنْدِي ضَعِيف قلت عَن عَليّ بن يزِيد وَغَيره فَقَالَ نعم"],[618,"قلت فعثمان بن أبي العاتكة فَقَالَ لَيْسَ بِشَيْء"],[619,"قَالَ أَبُو سعيد سَمِعت دحيما ينْسب عُثْمَان بن أبي العاتكة إِلَى الصدْق ويثني عَلَيْهِ وَيَقُول كَانَ معلم أهل دمشق"],[620,"قلت ليحيى الدَّرَاورْدِي مَا حَاله فَقَالَ لَا بَأْس بِهِ"],[621,"قلت ليحيى عبد الله بن وهب كَيفَ هُوَ عنْدك فَقَالَ أَرْجُو أَن يكون صَدُوقًا"],[622,"وَسَأَلته عَن عبد الله بن الديلمي كَيفَ حَدِيثه فَقَالَ ثِقَة"],[623,"قلت فعروة بن رُوَيْم فَقَالَ ثِقَة"],[624,"وَسَأَلته عَن عَليّ بن عبد الله بن عبد الرَّحْمَن بن عُثْمَان بن وثاب فَقَالَ شُيُوخ مدنيون لَيْسَ بهم بَأْس"],[625,"وَسَأَلته عَن عِيسَى بن الْمُغيرَة الحزامى فَقَالَ لَيْسَ بِهِ بَأْس"],[626,"وَسَأَلته عَن على بن ثَابت الْجَزرِي فَقَالَ ثِقَة"],[627,"قلت فيروي مُحَمَّد بن بشر عَن شيخ لَهُ يُقَال لَهُ عبد الله بن عبد الله مَا حَاله فَقَالَ لَا أعرفهُ"],[628,"وَسَأَلته عَن عبد الْحَكِيم بن مَنْصُور فَقَالَ لَيْسَ بِشَيْء"],[629,"وَسَأَلته عَن عُبَيْدَة فِي إِبْرَاهِيم فَقَالَ عُبَيْدَة لَيْسَ حَدِيثه بِشَيْء"],[630,"وَسَأَلته عَن عَليّ بن غراب كَيفَ هُوَ فَقَالَ هُوَ الْمِسْكِين صَدُوق قَالَ عُثْمَان عَليّ بن غراب لَيْسَ بِقَوي"],[631,"قلت ليحيى فعمر بن يعلى مَا حَاله فَقَالَ لَيْسَ بِشَيْء"],[632,"قلت فعائذ بن حبيب فَقَالَ ثِقَة"],[633,"قلت فعلي بن حَفْص حَدثنَا عَنهُ خلف المخرمي فَقَالَ الْمَدَائِنِي لَيْسَ بِهِ بَأْس"],[634,"قلت فعمرو بن عَاصِم الْكلابِي فَقَالَ أرَاهُ كَانَ صَدُوقًا"],[635,"قلت فعبيد الله بن عبد الْمجِيد الْحَنَفِيّ أَخُو أبي بكر مَا حَاله فَقَالَ لَيْسَ بِهِ بَأْس"],[636,"قلت قَالَ حَدثنَا أَبُو الْجمل فَقَالَ شيخ يمامي ضَعِيف"],[637,"قلت فعبد الْجَبَّار بن وهب الْكُوفِي تعرفه عَن عبد الله بن عبد الرَّحْمَن الْأنْصَارِيّ فَقَالَ مَا أعرفهم"],[638,"قلت فعبد السَّلَام الَّذِي يروي عَن حَمَّاد بن أبي سُلَيْمَان مَا حَاله فَقَالَ لَيْسَ بِهِ بَأْس قَالَ عُثْمَان هُوَ غير عبد السَّلَام بن حَرْب"],[639,"قلت فعبد الْخَالِق فَقَالَ ثِقَة"],[640,"قلت فعبد الله بن سلم يرْوى عَن بن عون مَا حَاله فَقَالَ لَا أعرفهُ"],[641,"قَالَ عُثْمَان سَمِعت القواريري يَقُول كَانَ عبد الله بن سلم من كتاب أَصْحَاب الزُّهْرِيّ وَابْن عون إِلَّا أَنه قل مَا كَانَ يحدث"],[642,"سَمِعت يحيى يَقُول عبيد بن يعِيش صَدُوق"],[643,"سَأَلت يحيى عَن عبد الله بن رَجَاء الْبَصْرِيّ فَقَالَ كَانَ شَيخا صَدُوقًا لَا بَأْس بِهِ"],[644,"قلت فعبد الله بن دَاوُد الْخُرَيْبِي فَقَالَ ثِقَة مَأْمُون"],[645,"قلت وَأَبُو عَاصِم أعنى النَّبِيل فَقَالَ ثِقَة"],[646,"قلت أَيهمَا أحب إِلَيْك فَقَالَ ثقتان قَالَ عُثْمَان الْخُرَيْبِي أَعلَى مِنْهُ"],[647,"قلت فعبد الْوَهَّاب بن مُجَاهِد فَقَالَ لَيْسَ بِشَيْء قَالَ عُثْمَان عبد الْوَهَّاب من أهل مَكَّة"],[648,"قلت ليحيى فعلباء بن أَحْمَر الَّذِي يروي عَنهُ دَاوُد بن أبي الْفُرَات فَقَالَ ثِقَة"],[649,"فعبد الْأَعْلَى عنْدك أثبت فِي سعيد أَو غنْدر فَقَالَ كل ثِقَة"],[650,"قلت فمعاذ أثبت فِي شُعْبَة أَو غنْدر فَقَالَ ثِقَة وَثَّقَهُ"],[651,"قلت مَا حَال وهب فِي أَيُّوب فَقَالَ ثِقَة"],[652,"هُوَ أحب إِلَيْك أَو الثَّقَفِيّ فَقَالَ ثِقَة وثقة"],[653,"قلت فعثمان بن عمر كَيفَ حَدِيثه فَقَالَ ثِقَة"],[654,"قلت فعطاء الكيخاراني كَيفَ حَدِيثه فَقَالَ ثِقَة"],[655,"قلت فعطاء بن الْمُبَارك تعرفه فَقَالَ من يروي عَنهُ قلت ذَاك الشَّيْخ أَحْمد بن بشير فَقَالَ هه كَأَنَّهُ يتعجب من ذكر أَحْمد بن بشير فَقَالَ لَا أعرفهُ قَالَ عُثْمَان أَحْمد بن بشير كَانَ من أهل الْكُوفَة ثمَّ قدم بَغْدَاد وَهُوَ مَتْرُوك"],[656,"قلت ليحيى فعبد الرَّحْمَن بن بديل بن ميسرَة فَقَالَ لَيْسَ بِهِ بَأْس"],[657,"قلت فعبد الْعَزِيز الْقَسْمَلِي فَقَالَ ثِقَة"],[658,"قلت هُوَ أحب إِلَيْك أَو أَبُو عوَانَة فَقَالَ كِلَاهُمَا ثِقَة"],[659,"قلت فعمران بن حدير فَقَالَ ثِقَة"],[660,"قلت فعنبسة بن عبد الرَّحْمَن فَقَالَ لَا أعرفهُ"],[661,"قلت فعنبسة بن سعيد فَقَالَ ثِقَة"],[662,"قلت فعيسى الحناط فَقَالَ لَيْسَ بِشَيْء"],[663,"قلت فالمسعودي كَيفَ حَدِيثه فَقَالَ هُوَ ثِقَة قلت هُوَ أحب إِلَيْك أَو مسعر فَقَالَ ثِقَة وثقة قَالَ عُثْمَان مسعر أتقن من المَسْعُودِيّ والمسعودي ثِقَة"],[664,"قلت ليحيى فعمر بن ذَر فَقَالَ ثِقَة"],[665,"قلت فَأَبُو الْحمانِي عبد الحميد فَقَالَ ثِقَة"],[666,"قلت فعمار بن سيف فَقَالَ ثِقَة"],[667,"قلت فعبد الْمجِيد بن عبد الْعَزِيز كَيفَ هُوَ فَقَالَ ثِقَة"],[668,"قلت فعثام بن عَليّ فَقَالَ ثِقَة"],[669,"قلت فعيسى بن يُونُس أحب إِلَيْك أَو أَبُو مُعَاوِيَة فَقَالَ ثِقَة وثقة"],[670,"قلت لَهُ فعبثر كَيفَ هُوَ فَقَالَ ثِقَة"],[671,"وَسَأَلته عَن عبد الحكم السدُوسِي فَقَالَ لَا أعرفهُ"],[672,"وسمعته يَقُول عبد الْكَرِيم بن أبي الْمخَارِق الْبَصْرِيّ أَبُو أُميَّة لَيْسَ بِشَيْء"],[673,"وَسَأَلته عَن عبد الرَّحْمَن بن سُلَيْمَان فَقَالَ ثِقَة"],[674,"وَسَأَلته عَن عبد المتعال بن طَالب فَقَالَ ثِقَة"],[675,"قلت ليحيى حَدثنَا عبد المتعال عَن بن وهب عَن عَمْرو عَن إِسْمَاعِيل بن أبي خَالِد عَن صلَة عَن خباب قَالَ قَالَ النَّبِي صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ الْخَيل ثَلَاثَة فَقَالَ لَيْسَ هَذَا بِشَيْء"],[676,"وَقَالَ يحيى الحكم بن مُوسَى ثِقَة"],[677,"والقواريري ثِقَة"],[678,"قلت ليحيى فَابْن نمير أحب إِلَيْك أَو بن إِدْرِيس فَقَالَ ثِقَة وثقة وَابْن إِدْرِيس أرفع"],[679,"وَسَأَلته عَن بن شَوْذَب كَيفَ حَدِيثه فَقَالَ ثِقَة"],[680,"وَسَأَلته عَن عُبَيْس بن مَيْمُون كَيفَ حَدِيثه فَقَالَ ضَعِيف حَدثنَا عُثْمَان قَالَ"],[681,"سَأَلت يحيى بن معِين قلت غَالب الْقطَّان تعرفه من هُوَ فَقَالَ ضَعِيف"],[682,"قلت فغسان بن مُضر فَقَالَ ثِقَة"],[683,"قلت فغاضرة بن قرهد فَقَالَ لَيْسَ بِهِ بَأْس حَدثنَا عُثْمَان قَالَ"],[684,"سَأَلت يحيى عَن فرقد السبخي فَقَالَ ثِقَة"],[685,"وسمعته يَقُول أَبُو أويس ضَعِيف الحَدِيث"],[686,"وفليح ضَعِيف وَقَالَ مَا أقربهما"],[687,"قلت ليحيى فالفرج بن فضَالة فَقَالَ لَيْسَ بِهِ بَأْس"],[688,"قلت فُضَيْل بن غَزوَان فَقَالَ ثِقَة"],[689,"قلت ففضيل بن مَرْزُوق فَقَالَ لَيْسَ بِهِ بَأْس قَالَ عُثْمَان يُقَال فُضَيْل بن مَرْزُوق ضَعِيف حَدثنَا عُثْمَان قَالَ"],[690,"قلت ليحيى قدامَة بن وبرة مَا حَاله فَقَالَ ثِقَة"],[691,"قلت وَالقَاسِم بن مخيمرة فَقَالَ ثِقَة أرَاهُ قَالَ كَانَ من أهل الْكُوفَة أَو غَيرهَا لَا أَدْرِي كَيفَ قَالَ فَنزل الشَّام"],[692,"وَسَأَلت يحيى بن معِين عَن الْقَاسِم بن فضل الْحدانِي فَقَالَ ثِقَة"],[693,"وَسَأَلته عَن قزعة بن سُوَيْد فَقَالَ ثِقَة"],[694,"حَدثنَا عُثْمَان قَالَ حَدثنَا يَعْقُوب الدَّوْرَقِي قَالَ حَدثنَا عبد الرَّحْمَن بن مهْدي قَالَ سَمِعت شُعْبَة يَقُول كنت أتفطن إِلَى فَم قَتَادَة فَإِذا قَالَ حَدثنَا كتبت وَإِذا قَالَ حدث لم أكتب"],[695,"حَدثنَا قَالَ سَأَلت يحيى عَن قراد أبي نوح فَقَالَ لَيْسَ بِهِ بَأْس"],[696,"قلت فقرة بن أبي الصَّهْبَاء يروي عَنهُ الْمُعْتَمِر كَيفَ هُوَ فَقَالَ مَا أعرفهُ"],[697,"وَسَأَلته عَن الْقَاسِم بن عَبَّاس الَّذِي يرْوى عَنهُ بن أبي ذِئْب فَقَالَ ثِقَة"],[698,"قلت قيس بن الرّبيع فَقَالَ لَيْسَ بِشَيْء"],[699,"سَمِعت يحيى يَقُول قَاسم المعمري خَبِيث كَذَّاب قَالَ عُثْمَان وَقد أدْركْت الْقَاسِم هَذَا المعمري كَانَ بِبَغْدَاد لَيْسَ كَمَا قَالَ يحيى"],[700,"قلت فالقعقاع بن حَكِيم فَقَالَ ثِقَة"],[701,"وَسَأَلته عَن قدامَة بن مُحَمَّد بن قدامَة بن خشرم فَقَالَ لَا أعرفهُ"],[702,"قلت فقدامة بن كُلْثُوم تعرفه فَقَالَ مَا أعرفهُ"],[703,"قلت حَدثنَا عَنهُ بن الطباع يحدث عَن شيخ لَهُ عَن أبي مجلز عَن مُعَاوِيَة قَالَ قَالَ النَّبِي صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ لَا يزَال الْمُسلمُونَ يظفرون مَا دَامَ اللِّوَاء فِي ربيعَة فَقَالَ مَا أعرفهُ قلت وَلَا الحَدِيث قَالَ وَلَا الحَدِيث حَدثنَا عُثْمَان قَالَ"],[704,"قلت ليحيى كثير بن عبد الله الْمُزنِيّ كَيفَ هُوَ فَقَالَ لَيْسَ بِشَيْء"],[705,"وَسَأَلته عَن الْكَوْثَر بن حَكِيم فَقَالَ لَيْسَ بِشَيْء"],[706,"وَسَأَلته عَن كُلْثُوم بن عمار فَقَالَ ثِقَة"],[707,"قلت كُلَيْب بن صبح فَقَالَ ثِقَة"],[708,"وَسَأَلت يحيى قلت كنَانَة بن جبلة الَّذِي كَانَ يكون بخراسان من أهل الحَدِيث قَالَ ذَاك كَذَّاب خَبِيث قَالَ عُثْمَان وَهُوَ قريب مِمَّا قَالَ يحيى خَبِيث الحَدِيث"],[709,"قَالَ وَسَأَلته عَن كثير بن شنظير كَيفَ هُوَ فَقَالَ ثِقَة حَدثنَا عُثْمَان قَالَ"],[710,"قلت ليحيى فالليث أَعنِي بن سعد أحب إِلَيْك أَو يحيى بن أَيُّوب فَقَالَ اللَّيْث أحب إِلَيّ وَيحيى ثِقَة"],[711,"قلت مَا حَال لَيْث بن أبي سليم فَقَالَ ضَعِيف حَدثنَا عُثْمَان قَالَ"],[712,"سَأَلت يحيى بن معِين عَن مُحَمَّد بن مُسلم الطَّائِفِي فَقَالَ ثِقَة"],[713,"قلت فَأَبُو الزبير فَقَالَ ثِقَة"],[714,"وَسَأَلته عَن مُحَمَّد بن زيد بن قنفذ فَقَالَ ثِقَة"],[715,"قلت معبد بن خَالِد فَقَالَ ثِقَة"],[716,"قلت فَأَبُو ظَبْيَة الَّذِي يروي عَنهُ مُحَمَّد بن سعد الْأنْصَارِيّ فَقَالَ ثِقَة"],[717,"قلت مُحَمَّد بن مطرف مَا حَاله فَقَالَ أَبُو غَسَّان لَيْسَ بِهِ بَأْس"],[718,"وَسَأَلته عَن مُحَمَّد بن زِيَاد فَقَالَ ثِقَة"],[719,"قلت فالألهاني فَقَالَ كِلَاهُمَا ثقتان"],[720,"قلت فمحمد بن أبي يَعْقُوب الَّذِي يروي عَنهُ مهْدي بن مَيْمُون مَا حَاله فَقَالَ ثِقَة"],[721,"قلت مَا حَال مطرح أبي الْمُهلب فَقَالَ لَيْسَ بِشَيْء قَالَ أَبُو سعيد يُقَال لَهُ مطرح بن يزِيد"],[722,"قلت فمسلمة بن زِيَاد فَقَالَ ثِقَة"],[723,"قلت مُوسَى بن عُبَيْدَة فَقَالَ ضَعِيف"],[724,"قلت فمعمر بن أبي حيية فَقَالَ ثِقَة"],[725,"قلت مُحَمَّد بن إِسْحَاق عَن أبي سُفْيَان مَا حَال أبي سُفْيَان هَذَا فَقَالَ ثِقَة مَشْهُور"],[726,"قلت عَن مُسلم بن كثير عَن عَمْرو بن حريش الزبيدِيّ فَقَالَ هَذَا حَدِيث مَشْهُور"],[727,"وَسَأَلته عَن مَيْمُون بن أستاد فَقَالَ ثِقَة"],[728,"قلت فمحمد بن عبد الرَّحْمَن مولى آل طَلْحَة فَقَالَ لَيْسَ بِهِ بَأْس"],[729,"قلت فمحمد بن سوقة فَقَالَ ثِقَة"],[730,"قلت فمحمد بن عثيم من هُوَ فَقَالَ لَيْسَ بِشَيْء"],[731,"قلت فمحمد بن عبد الرَّحْمَن الْبَيْلَمَانِي فَقَالَ لَيْسَ بِشَيْء"],[732,"وَسَأَلته عَن ملازم بن عَمْرو فَقَالَ ثِقَة"],[733,"قلت فمحمد بن جَابر اليمامي مَا حَاله فَقَالَ لَيْسَ بِشَيْء"],[734,"قلت فمعقل بن عبيد الله فَقَالَ لَيْسَ بِهِ بَأْس"],[735,"قلت فمعمر بن سُلَيْمَان فَقَالَ ثِقَة"],[736,"قلت فمروان بن مُعَاوِيَة فَقَالَ ثِقَة"],[737,"وَسَأَلته عَن مُحَمَّد فضاء فَقَالَ ضَعِيف قَالَ عُثْمَان مُحَمَّد بن فضاء بَصرِي"],[738,"سَأَلت يحيى بن مُجَاهِد بن رومي فَقَالَ ثِقَة"],[739,"وَسَأَلت يحيى قلت مَسْرُوق أحب إِلَيْك عَن عَائِشَة أَو عُرْوَة فَلم يُخَيّر"],[740,"وَسَأَلت يحيى قلت مُحَمَّد بن الْمُنْكَدر أحب إِلَيْك عَن جَابر أَو أَبُو الزبير فَقَالَ ثقتان"],[741,"قلت ليحيى هِشَام بن عُرْوَة أحب إِلَيْك عَن أَبِيه أَو الزُّهْرِيّ عَنهُ فَقَالَ كِلَاهُمَا وَلم يفضل"],[742,"قلت فموسى بن عقبَة فَقَالَ ثِقَة"],[743,"قلت فمعاوية بن يحيى الصَّدَفِي فَقَالَ لَيْسَ بِشَيْء"],[744,"قلت فَمُسلم الْخياط الَّذِي يروي عَنهُ بن أبي ذِئْب فَقَالَ ثِقَة"],[745,"قلت فالمنكدر بن مُحَمَّد بن الْمُنْكَدر فَقَالَ لَيْسَ بِهِ بَأْس"],[746,"قلت فمشرح بن هاعان فَقَالَ ثِقَة قَالَ عُثْمَان ومشرح لَيْسَ بِذَاكَ وَهُوَ صَدُوق"],[747,"قلت فمسلمة بن عَليّ فَقَالَ لَيْسَ بِشَيْء"],[748,"قلت فالمفضل بن فضَالة مَا حَاله فَقَالَ ثِقَة"],[749,"قلت لَهُ مخلد بن يزِيد مَا حَاله فَقَالَ ثِقَة"],[750,"قلت فَابْن حمير أَعنِي مُحَمَّد بن حمير الْحِمصِي فَقَالَ ثِقَة"],[751,"وَسَأَلته عَن مُبشر بن إِسْمَاعِيل فَقَالَ ثِقَة"],[752,"قلت فمسكين بن بكير فَقَالَ لَيْسَ بِهِ بَأْس"],[753,"قلت فمحمد بن بشر فَقَالَ ثِقَة"],[754,"وَسَأَلته عَن منْدَل بن عَليّ فَقَالَ لَيْسَ بِهِ بَأْس"],[755,"قلت فمخلد بن يزِيد مَا حَاله فَقَالَ ثِقَة"],[756,"وَسَأَلت يحيى عَن مُحَمَّد بن طَلْحَة فَقَالَ لَيْسَ بِهِ بَأْس"],[757,"وَسَأَلت يحيى عَن مري بن قطري فَقَالَ ثِقَة"],[758,"وَسَأَلته عَن مطر بن عكامس لَقِي النَّبِي صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقَالَ لَا أعلمهُ وَمَا يرْوى عَنهُ إِلَّا هَذَا الحَدِيث"],[759,"وَسمعت يحيى يَقُول مُحَمَّد بن عباد بن جَعْفَر المَخْزُومِي الَّذِي يروي عَنهُ بن جريج ثِقَة مَشْهُور"],[760,"وَسَأَلته عَن مَيْمُون الْكرْدِي مَا حَاله فَقَالَ لَيْسَ بِهِ بَأْس"],[761,"قلت فمشاش فَقَالَ ثِقَة"],[762,"وَسَأَلته عَن مُحَمَّد بن جحادة مَا حَاله فَقَالَ ثِقَة"],[763,"قلت فموسى بن سَالم الَّذِي يروي عَنهُ بن عِلّة كَيفَ حَاله فَقَالَ ثِقَة"],[764,"قلت ليحيى فَشَيْخ يرْوى عَنهُ البرْسَانِي يُقَال لَهُ مَيْمُون أَبُو مُحَمَّد تعرفه فَقَالَ لَا أعرفهُ"],[765,"وَسَأَلته عَن مُصعب بن ثَابت قلت كَيفَ حَدِيثه فَقَالَ ضَعِيف"],[766,"قلت فنافع بن سُلَيْمَان كَيفَ حَدِيثه فَقَالَ هُوَ ثِقَة"],[767,"قلت يروي عَن مُحَمَّد بن أبي صَالح مَا حَاله فَقَالَ لَا أعرفهُ"],[768,"قلت ليحيى فمعاوية بن معبد بن كَعْب فَقَالَ لَا أعرفهُ"],[769,"قلت فمعاذ بن عبد الله عَن عبد الله عَن أَبِيه كَيفَ هَؤُلَاءِ فَقَالَ ثِقَات"],[770,"قلت فمحمد بن عمار الَّذِي يروي عَنهُ معن فَقَالَ لَا أعرفهُ"],[771,"قلت فمحمد بن عمار بن سعد فَقَالَ لَا أعرفهُ"],[772,"وَسَأَلت يحيى عَن مُحَمَّد بن يزِيد بن ركَانَة فَقَالَ ثِقَة"],[773,"قلت فمحمد بن أبي عَائِشَة الَّذِي يروي عَن أبي هُرَيْرَة فَقَالَ هُوَ ثِقَة"],[774,"قلت ليحيى فمالك بن عُبَيْدَة الديلِي تعرفه عَن أَبِيه عَن جده عَن النَّبِي صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ لَوْلَا رجال خشع فَقَالَ مَا أعرفهُ"],[775,"قلت ليحيى فزكريا بن مَنْظُور عَن مُحَمَّد بن عقبَة فَقَالَ هُوَ أَخُو إِبْرَاهِيم بن عقبَة ثِقَة"],[776,"قلت ليحيى فموسى بن وردان كَيفَ حَدِيثه فَقَالَ لَيْسَ بِالْقَوِيّ"],[777,"قلت فمعاوية بن سَلام فَقَالَ ثِقَة"],[778,"قلت فمحمد بن مهَاجر فَقَالَ ثِقَة"],[779,"قلت فمثنى بن صباح فَقَالَ ضَعِيف"],[780,"وَسَأَلته عَن مدرك بن سعد الشَّامي فَقَالَ ثِقَة"],[781,"وَسَأَلت يحيى عَن منخل بن حَكِيم فَقَالَ لَا أعرفهُ قلت حَدثنَا عَنهُ بن الْجَعْد فَقَالَ مَا أعرفهُ"],[782,"وَسَأَلته عَن مَحْفُوظ بن عَلْقَمَة كَيفَ حَدِيثه فَقَالَ ثِقَة"],[783,"وَسَأَلته عَن الْمعَافي بن عمرَان فَقَالَ ثِقَة"],[784,"قلت فمحمد بن ميسرَة الَّذِي يروي عَنهُ أَبُو مُعَاوِيَة مَا حَاله فَقَالَ لَيْسَ بِهِ بَأْس"],[785,"وَسَأَلته عَن مُحَمَّد بن الْحسن بن أبي الْحسن المَخْزُومِي بن زبالة فَقَالَ لَيْسَ بِثِقَة"],[786,"وَسَأَلت يحيى عَن أبي سُفْيَان الَّذِي يروي عَن معمر مَا حَاله فَقَالَ رجل صَدُوق"],[787,"قلت ليحيى فالمسيب بن شريك فَقَالَ لَيْسَ بِشَيْء"],[788,"قلت مُحَمَّد بن ربيعَة الْكُوفِي من هُوَ فَقَالَ ثِقَة"],[789,"قلت مُحَمَّد بن الْحجَّاج اللَّخْمِيّ الوَاسِطِيّ كَيفَ هُوَ فَقَالَ كَذَّاب"],[790,"قلت فمروان بن نهيك فَقَالَ لَا أعرفهُ"],[791,"وَسَأَلته عَن يزِيد الرشك كَيفَ حَدِيثه فَقَالَ ثِقَة"],[792,"قلت فمعاذة الَّتِي يروي عَنْهَا كَيفَ هِيَ قَالَ يسْأَل أحد عَن معَاذَة ثِقَة"],[793,"قلت أَزْهَر السمان كَيفَ حَدِيثه فَقَالَ ثِقَة"],[794,"قلت فمعاذ بن معَاذ فَقَالَ ثِقَة قلت أَيهمَا أثبت فِي بن عون فَقَالَ ثقتان"],[795,"قلت والبرساني فَقَالَ ثِقَة"],[796,"قلت فمحمد بن يزِيد الوَاسِطِيّ فَقَالَ ثِقَة"],[797,"وَسَأَلته عَن مجمع بن يَعْقُوب كَيفَ حَدِيثه فَقَالَ لَيْسَ بِهِ بَأْس"],[798,"قلت فالمبارك بن حسان كَيفَ حَدِيثه فَقَالَ ثِقَة"],[799,"وَسَأَلته عَن مُحَمَّد بن علاثة من هُوَ فَقَالَ ثِقَة"],[800,"قلت مُحَمَّد بن ثَابت الْعَبْدي فَقَالَ لَيْسَ بِهِ بَأْس"],[801,"قلت فمحمد بن عبد الْكَرِيم الْبَصْرِيّ فَقَالَ الضال لَا بَأْس بِهِ قَالَ عُثْمَان الضال لقب كَانَ شَيخا مغفلا يُمْسِي فيضل فِي الطَّرِيق فَقيل لَهُ الضال"],[802,"قلت ليحيى فمجالد كَيفَ حَدِيثه فَقَالَ صَالح كَأَنَّهُ"],[803,"وَسَأَلته عَن مُسَافر الْجَصَّاص فَقَالَ ثِقَة"],[804,"قلت فمحمد بن عبد الْعَزِيز التَّيْمِيّ الْكُوفِي تعرفه حَدثنَا عَنهُ بن يُونُس فَقَالَ لَا أعرفهُ"],[805,"قَالَ عُثْمَان كَانَ مُحَمَّد بن عبد الْعَزِيز ثِقَة كَانَ أَحْمد بن يُونُس يذكر عَنهُ خيرا وفضلا خرج من الْكُوفَة وَقَالَ لَا أقيم ببلدة يشْتم فِيهَا أَصْحَاب النَّبِي صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ"],[806,"سَأَلت يحيى بن معِين عَن مَرْحُوم الْعَطَّار فَقَالَ ثِقَة"],[807,"وَسَأَلته عَن الْمُعَلَّى بن مَنْصُور فَقَالَ ثِقَة"],[808,"وَسَأَلته عَن مَنْصُور بن أبي مُزَاحم فَقَالَ صَدُوق إِن شَاءَ الله"],[809,"وَسَأَلته عَن مُحَمَّد بن بكار فَقَالَ شيخ لَا بَأْس بِهِ"],[810,"قلت فَابْن أبي فديك فَقَالَ ثِقَة"],[811,"قلت فمنهال بن خَليفَة فَقَالَ ضَعِيف حَدثنَا عُثْمَان قَالَ"],[812,"سَأَلت يحيى بن معِين عَن نبيط بن شريط فَقَالَ هُوَ أَبُو سَلمَة ثِقَة"],[813,"قلت النَّضر بن عَرَبِيّ مَا حَاله فَقَالَ ثِقَة قَالَ عُثْمَان النَّضر بن عَرَبِيّ لَيْسَ بِهِ بَأْس وَلَيْسَ بِذَاكَ"],[814,"وَسَأَلت يحيى عَن نوح بن قيس فَقَالَ ثِقَة"],[815,"وَسَأَلته عَن النهاس بن قهم فَقَالَ ضَعِيف"],[816,"قلت فنافع بن عمر فَقَالَ ثِقَة"],[817,"وَسَأَلته عَن نَافِع أبي هُرْمُز الْجمال من هُوَ فَقَالَ لَا أعرفهُ"],[818,"وَسَأَلته عَن النَّضر بن شُمَيْل فَقَالَ ثِقَة"],[819,"قلت النَّضر بن مَنْصُور الْعَنزي يعرفهُ يروي عَنهُ بن أبي معشر عَن أبي الْجنُوب عَن عَليّ من هَؤُلَاءِ فَقَالَ هَؤُلَاءِ حمالَة الْحَطب"],[820,"وَسَأَلته عَن أبي معشر الْمَدِينِيّ فَقَالَ اسْمه نجيح ضَعِيف"],[821,"وَسَأَلته عَن أبي مكين نوح فَقَالَ ثِقَة"],[822,"قلت فنافع بن سُلَيْمَان كَيفَ حَدِيثه فَقَالَ ثِقَة"],[823,"قلت فنصر بن على الْحدانِي فَقَالَ ثِقَة"],[824,"وَسَأَلته عَن أبي طعمة فَقَالَ نسير ثِقَة حَدثنَا عُثْمَان قَالَ"],[825,"سَأَلت يحيى عَن وهب بن جَابر فَقَالَ ثِقَة"],[826,"وَسَأَلته عَن الْوَلِيد بن كثير فَقَالَ لَيْسَ بِهِ بَأْس"],[827,"وَسَأَلته عَن وَاقد بن مُحَمَّد بن زيد فَقَالَ ثِقَة"],[828,"قلت فالموقري الْوَلِيد بن مُحَمَّد فَقَالَ لَيْسَ بِشَيْء"],[829,"وَسَأَلته عَن الْوَلِيد بن جَمِيع فَقَالَ ثِقَة"],[830,"قلت فوهب بن أبي ذبي يروي عَنهُ دَيْلَم بن غَزوَان من هُوَ فَقَالَ ثِقَة"],[831,"قلت مَا حَال وهيب فِي أَيُّوب فَقَالَ ثِقَة"],[832,"قلت فوهيب بن الْورْد فَقَالَ ثِقَة"],[833,"قلت فوهب بن جرير كَيفَ حَدِيثه فَقَالَ ثِقَة حَدثنَا عُثْمَان قَالَ"],[834,"سَأَلت يحيى بن معِين عَن هِلَال بن خباب فَقَالَ ثِقَة"],[835,"وَسَأَلته عَن الْهَيْثَم بن جماز فَقَالَ لَيْسَ بِشَيْء"],[836,"وَسَأَلته عَن هزال أبي حتريش فَقَالَ لَيْسَ بِشَيْء"],[837,"وَسَأَلته عَن هِشَام بن حسان فَقَالَ ثِقَة"],[838,"قلت هُوَ أحب إِلَيْك أَو جرير بن حَازِم فَقَالَ هِشَام أحب إِلَيّ"],[839,"قلت ليحيى فهشام بن حسان أحب إِلَيْك فِي بن سِيرِين أَو يزِيد بن إِبْرَاهِيم فَقَالَ كِلَاهُمَا ثقتان"],[840,"حَدثنَا عُثْمَان قَالَ سَمِعت أَبَا الْوَلِيد الطَّيَالِسِيّ يَقُول يزِيد بن إِبْرَاهِيم أثبت عندنَا من هِشَام بن حسان"],[841,"سَأَلت يحيى قلت سُفْيَان بن حُسَيْن هِشَام بن يُوسُف من هِشَام هَذَا فَقَالَ لَا أعرفهُ"],[842,"قلت فهمام بن مُنَبّه كَيفَ حَدِيثه فَقَالَ ثِقَة"],[843,"وَسَأَلته عَن هريم فَقَالَ ثِقَة"],[844,"قلت فهرير الَّذِي يروي عَنهُ أَبُو إِسْمَاعِيل الْمُؤَدب من هُوَ فَقَالَ ثِقَة"],[845,"وَسَأَلته عَن هَارُون بن سعد كَيفَ هُوَ فَقَالَ لَيْسَ بِهِ بَأْس"],[846,"قلت فهارون النَّحْوِيّ فَقَالَ ثِقَة"],[847,"قلت فهلال بن مَيْمُون الْجُهَنِيّ فَقَالَ صَالح"],[848,"وَسَأَلته عَن هياج بن بسطَام فَقَالَ لَيْسَ بِشَيْء"],[849,"قلت فهاشم بن الْقَاسِم مَا حَاله فَقَالَ ثِقَة حَدثنَا عُثْمَان قَالَ"],[850,"سَأَلت يحيى بن معِين عَن يحيى بن سليم الطَّائِفِي فَقَالَ ثِقَة"],[851,"قلت يزِيد بن أبي زِيَاد بن أبي الْجَعْد فَقَالَ لَيْسَ بِهِ بَأْس"],[852,"وَسَأَلته عَن يُوسُف بن الْمَاجشون فَقَالَ لَيْسَ بِهِ بَأْس"],[853,"قلت فيونس بن خباب فَقَالَ ضَعِيف"],[854,"قلت يعلى بن عَطاء فَقَالَ ثِقَة"],[855,"وَسَأَلته عَن يُوسُف بن مَاهك فَقَالَ ثِقَة"],[856,"قلت فيحيى بن أبي أنيسَة فَقَالَ لَيْسَ بِشَيْء"],[857,"قلت فيزيد بن إِبْرَاهِيم أحب إِلَيْك أَو جَعْفَر بن حَيَّان فَقَالَ يزِيد أحب إِلَيّ"],[858,"وَسَأَلت يحيى عَن يحيى بن ضريس كَيفَ هُوَ فَقَالَ ثِقَة"],[859,"قلت فيعلى بن الْحَارِث فَقَالَ ثِقَة"],[860,"قلت فيحيى بن آدم مَا حَاله فِي سُفْيَان فَقَالَ ثِقَة"],[861,"وَسَأَلته عَن يحيى بن عبيد الله عَن أَبِيه عَن أبي هُرَيْرَة مَا حَاله فَقَالَ لَيْسَ بِشَيْء"],[862,"وَسَأَلته عَن يزِيد بن عِيَاض بن جعدبة فَقَالَ لَيْسَ بِشَيْء"],[863,"قلت فيزيد بن خمير فَقَالَ ثِقَة"],[864,"قلت فيحيى بن سعيد الْحِمصِي الْعَطَّار فَقَالَ لَيْسَ بِشَيْء"],[865,"قلت يُوسُف بن أَسْبَاط تعرفه فَقَالَ ثِقَة"],[866,"وَسَأَلته عَن يُونُس بن بكير كَيفَ حَدِيثه فَقَالَ ثِقَة قَالَ عُثْمَان يُخَالف فِي يُونُس"],[867,"وَسَأَلته عَن يُونُس بن مُحَمَّد فَقَالَ ثِقَة"],[868,"وَسَأَلته عَن يحيى بن أبي بكير فَقَالَ ثِقَة"],[869,"وَسَأَلته عَن يزِيد بن أبي زِيَاد فَقَالَ لَيْسَ بِالْقَوِيّ"],[870,"قلت فيوسف بن صُهَيْب فَقَالَ كُوفِي ثِقَة"],[871,"وَسَأَلته عَن يزِيد الدالاني فَقَالَ لَيْسَ بِهِ بَأْس"],[872,"قلت فيزيد بن رُومَان فَقَالَ ثِقَة"],[873,"قلت فيزيد بن مُحَمَّد بن خثيم فَقَالَ لَيْسَ بِهِ بَأْس"],[874,"قلت فيزيد بن عبد الْملك الَّذِي يروي عَنهُ معن فَقَالَ مَا كَانَ بِهِ بَأْس"],[875,"وَسَأَلته عَن يحيى بن عباد بن عبد الله بن الزبير كَيفَ هُوَ فَقَالَ ثِقَة"],[876,"وَسَأَلته عَن يَعْقُوب بن إِبْرَاهِيم بن سعد فَقَالَ ثِقَة"],[877,"قلت وَأَخُوهُ سعد فَقَالَ ثِقَة"],[878,"وَسَأَلته عَن يُونُس بن سليم الَّذِي يروي عَنهُ عبد الرَّزَّاق فَقَالَ مَا أعرفهُ يروي عَنهُ عبد الرَّزَّاق"],[879,"وَسَأَلته عَن يَعْقُوب بن عتبَة كَيفَ حَدِيثه فَقَالَ هُوَ ثِقَة"],[880,"وَسَأَلته عَن يزِيد بن قسيط مَا حَاله فَقَالَ صَالح"],[881,"وَسَأَلته عَن يحيى بن زبان فَقَالَ لَا أعرفهُ"],[882,"قلت فروى عَن عبد الله بن رَاشد من هُوَ فَقَالَ لَا أعرفهُ"],[883,"قلت فيزيد بن أبي مَرْيَم مَا حَاله فَقَالَ ثِقَة"],[884,"قلت فيحيى بن عِيسَى الرَّمْلِيّ تعرفه فَقَالَ نعم مَا هُوَ بِشَيْء"],[885,"وَسَأَلته عَن يزِيد الشَّامي عَن الزُّهْرِيّ من هُوَ يروي عَنهُ مَرْوَان بن مُعَاوِيَة قَالَ هُوَ يزِيد بن سِنَان أَبُو فَرْوَة لَيْسَ بِشَيْء"],[886,"وَسَأَلته عَن يُونُس بن الْقَاسِم قَالَ أرَاهُ اليمامي ثِقَة"],[887,"قلت فابنه عمر فَقَالَ ثِقَة"],[888,"وَسَأَلته عَن يُوسُف بن خَالِد فَقَالَ هُوَ السَّمْتِي لَيْسَ بِثِقَة وَسَأَلته قلت يروي عَن عَمْرو أبي البكرات كَيفَ هُوَ فَقَالَ لَيْسَ بِثِقَة عَمَّن روى"],[889,"سَأَلت يحيى عَن يُونُس بن سليم فَقَالَ مَا أعرفهُ"],[890,"سَمِعت يحيى يَقُول بن الْحمانِي صَدُوق مَشْهُور مَا بِالْكُوفَةِ مثل بن الْحمانِي مَا يُقَال فِيهِ إِلَّا من حسد قَالَ عُثْمَان وَكَانَ بن الْحمانِي شَيخا فِيهِ غَفلَة لم يكن يقدر أَن يصون نَفسه كَمَا يفعل أَصْحَاب الحَدِيث"],[891,"قلت فَأَبُو عقيل يحيى بن المتَوَكل فَقَالَ لَيْسَ بِهِ بَأْس قَالَ عُثْمَان هُوَ ضَعِيف"],[892,"قلت ليحيى فالدورقي أَعنِي أَبَا عقيل الدَّوْرَقِي فَقَالَ ثِقَة"],[893,"وَسَأَلته عَن يزِيد الرشك كَيفَ حَدِيثه فَقَالَ ثِقَة"],[894,"وَسَأَلته عَن يحيى بن عَتيق كَيفَ هُوَ فَقَالَ ثِقَة"],[895,"قلت هُوَ أحب إِلَيْك فِي بن سِيرِين أَو هِشَام بن حسان فَقَالَ ثِقَة وثقة قَالَ عُثْمَان يحيى بن عَتيق خير"],[896,"قلت ليحيى فاليمان بن الْمُغيرَة كَيفَ حَدِيثه فَقَالَ لَيْسَ بِشَيْء"],[897,"قلت فيونس بن عبيد أحب إِلَيْك فِي الْحسن أَو حميد فَقَالَ كِلَاهُمَا قَالَ عُثْمَان يُونُس أَكثر بِكَثِير"],[898,"وَسَأَلت يحيى عَن يحيى بن سَلمَة بن كهيل فَقَالَ لَيْسَ بِشَيْء"],[899,"وَسَأَلته عَن يحيى بن عبد الْملك بن أبي غنية كَيفَ هُوَ فَقَالَ ثِقَة قلت فأبوه فَقَالَ ثِقَة"],[900,"قلت فياسين الزيات فَقَالَ لَيْسَ بِشَيْء"],[901,"قلت فيحيى بن أَيُّوب البَجلِيّ مَا حَاله فَقَالَ لَيْسَ بِهِ بَأْس قَالَ عُثْمَان يحيى بن أَيُّوب البَجلِيّ كُوفِي"],[902,"قلت ليحيى يُونُس بن أبي إِسْحَاق أحب إِلَيْك أَو إِسْرَائِيل فَقَالَ كل ثِقَة"],[903,"وَسَأَلته عَن يحيى بن وَاضح فَقَالَ لَيْسَ بِهِ بَأْس"],[904,"سَمِعت يحيى يَقُول يزِيد بن مَرْوَان الْخلال كذ اب قَالَ عُثْمَان وَقد أدْركْت يزِيد بن مَرْوَان وَهُوَ ضَعِيف قريب مِمَّا قَالَ يحيى"],[905,"قَالَ عُثْمَان وَيزِيد بن عبد الله الْحِمصِي الجرجسي ثِقَة صَاحب حَدِيث حَدثنَا عُثْمَان قَالَ"],[906,"سَأَلت يحيى بن معِين عَن أبي ظَبْيَة الَّذِي يروي عَنهُ مُحَمَّد بن سعد الْأنْصَارِيّ فَقَالَ ثِقَة"],[907,"قلت فَأَبُو العنبس عَن أبي الْعَدَبَّس مَا حَالهمَا فَقَالَ ثقتان"],[908,"قلت فَأَبُو غَالب الَّذِي يرْوى عَن أبي أُمَامَة مَا حَاله فَقَالَ ثِقَة"],[909,"قلت وَأَبُو يَعْفُور عَن أَيمن مَا حَالهمَا فَقَالَ ثقتان"],[910,"وَسَأَلته عَن أبي جَعْفَر الخطمي فَقَالَ ثِقَة"],[911,"قلت فالنجراني من هُوَ فَقَالَ رجل مَشْهُور"],[912,"وَسَأَلته عَن أبي المتَوَكل النَّاجِي فَقَالَ ثِقَة"],[913,"قلت هُوَ أحب إِلَيْك أَو أَبُو نَضرة فَقَالَ كِلَاهُمَا ثقتان"],[914,"وَسَأَلته عَن أبي قبيل الْمعَافِرِي فَقَالَ ثِقَة"],[915,"قلت فَأَبُو جَمِيع سَالم فَقَالَ ثِقَة"],[916,"قلت فَأَبُو الزَّاهِرِيَّة فَقَالَ ثِقَة"],[917,"وَسَأَلته عَن أبي كُدَيْنَة فَقَالَ ثِقَة"],[918,"وَسَأَلته عَن أبي وَكِيع فَقَالَ لَيْسَ بِهِ بَأْس"],[919,"وَسَأَلته عَن أبي جناب الْكَلْبِيّ فَقَالَ هُوَ صَدُوق قَالَ عُثْمَان هُوَ ضَعِيف"],[920,"قلت فَأَبُو زرْعَة بن عَمْرو بن جرير فَقَالَ ثِقَة"],[921,"قلت فَابْن أبي أويس أَخُو هَذَا الْحَيّ فَقَالَ كَانَ ثِقَة"],[922,"قلت فَهَذَا الْحَيّ فَقَالَ لَا بَأْس بِهِ"],[923,"قلت فَأَبُو زميل كَيفَ حَدِيثه فَقَالَ ثِقَة"],[924,"قلت فَأَبُو عشانة الْمعَافِرِي فَقَالَ ثِقَة"],[925,"قلت فَأَبُو تَمِيم الجيشاني فَقَالَ هَؤُلَاءِ ثِقَات"],[926,"قلت فَأَبُو الْهَيْثَم الَّذِي يروي عَنهُ دراج فَقَالَ ثِقَة"],[927,"قلت فَأَبُو صَخْر فَقَالَ ثِقَة"],[928,"وَسَأَلته عَن أبي الْفَيْض أَعنِي الَّذِي يروي عَنهُ شُعْبَة كَيفَ حَدِيثه فَقَالَ ثِقَة"],[929,"وَسَأَلته عَن أبي الْمليح الرقي فَقَالَ ثِقَة"],[930,"قَالَ عُثْمَان قَالَ لي يحيى لَا تكْتب عَن بن القرين شيخ بِبَغْدَاد من ذَاك الْجَانِب فَإِنَّهُ كَذَّاب خَبِيث"],[931,"قلت ليحيى وَأَبُو بكر الْحَنَفِيّ فَقَالَ لَيْسَ بِهِ بَأْس"],[932,"وَسَأَلته عَن أبي خَالِد الْأَحْمَر فَقَالَ لَيْسَ بِهِ بَأْس"],[933,"وَسَأَلته عَن أبي بكر النَّهْشَلِي فَقَالَ ثِقَة"],[934,"قَالَ عُثْمَان سَمِعت أَحْمد بن يُونُس يَقُول كَانَ أَبُو بكر النَّهْشَلِي شَيخا صَالحا مغفلا وَكَانَ فِي مَرضه حِين مَاتَ يثب للصَّلَاة وَلَا يقدر فَيُقَال لَهُ إِنَّك فِي عذر أَنْت ضَعِيف فَيَقُول أبادرطي صحيفتي"],[935,"وَسَأَلت يحيى عَن أبي إِسْحَاق الْكُوفِي الَّذِي يروي عَنهُ هشيم فَقَالَ هُوَ عبد الله بن ميسرَة"],[936,"قلت فَمن أَبُو إِسْحَاق هَارُون ذَا الَّذِي يروي عَنهُ حَمَّاد بن زيد فَقَالَ هَذَا لَيْسَ ذَاك هَذَا ثِقَة لوكان هَذَا مثل ذَاك يَعْنِي مثل بن ميسرَة هلك"],[937,"قلت فَأَبُو إِسْمَاعِيل أَعنِي الْمُؤَدب مَا حَاله فَقَالَ ثِقَة"],[938,"قلت فَأَبُو سعيد الْمُؤَدب أَعنِي مولى بني هَاشم فَقَالَ هُوَ ثِقَة"],[939,"وَسَأَلته عَن ربيعَة الَّذِي يروي عَنهُ شريك فَقَالَ هُوَ كُوفِي ثِقَة"],[940,"قلت فَأَبُو شيبَة الَّذِي يروي عَنهُ يزِيد فَقَالَ أَبُو هَؤُلَاءِ قلت نعم فَقَالَ لَيْسَ بِثِقَة"],[941,"قلت فَأَبُو ربيعَة صَاحب السابري كَيفَ هُوَ فَقَالَ لَيْسَ بِهِ بَأْس"],[942,"وَسَأَلته عَن أبي فَرْوَة فَقَالَ ثِقَة"],[943,"وَسمعت يحيى وَسُئِلَ عَن الرجل يلقِي الرجل الضَّعِيف من بَين ثقتين يُوصل الحَدِيث ثِقَة عَن ثِقَة وَيَقُول أنقص من الحَدِيث وأصل ثِقَة عَن ثِقَة يحسن الحَدِيث بذلك فَقَالَ لَا يفعل لَعَلَّ الحَدِيث عَن كَذَّاب لَيْسَ بِشَيْء فَإِذا هُوَ قد حسنه وثبته وَلَكِن يحدث بِهِ كَمَا رُوِيَ قَالَ عُثْمَان وَكَانَ الْأَعْمَش رُبمَا فعل ذَلِك"],[944,"وَسَأَلت يحيى عَن أبي بكر بن شُعَيْب بن الحبحاب مَا حَاله فَقَالَ لَيْسَ بِهِ بَأْس"],[945,"قلت فَأَبُو الْأسود الْغِفَارِيّ عَن النُّعْمَان الْغِفَارِيّ عَن أبي ذَر أَن النَّبِي صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ يَا أَبَا ذَر اعقل من هما فَقَالَ مَا أَعْرفهُمَا"],[946,"وَسَأَلته عَن أبي صَالح الْحَنَفِيّ كَيفَ حَدِيثه فَقَالَ ثِقَة"],[947,"قلت هُوَ أصح حَدِيثا أَو ذكْوَان فَقَالَ كِلَاهُمَا ثِقَة"],[948,"وَسَأَلته عَن مولى سِبَاع الَّذِي روى حَدِيث أبي بكر فَقَالَ مَا أعرفهُ"],[949,"وَسَأَلته عَن أبي معشر الْمدنِي فَقَالَ ضَعِيف"],[950,"وَسَأَلته عَن أبي الْعَلَاء الْخفاف كَيفَ هُوَ فَقَالَ ضَعِيف"],[951,"قلت فحيان أبي النَّضر مَا حَاله فَقَالَ ثِقَة"],[952,"وَسَأَلته عَن أبي دراس مَا حَاله فَقَالَ إِنَّمَا يروي حَدِيثا وَاحِدًا لَيْسَ بِهِ بَأْس"],[953,"قلت فَأَبُو سَلمَة مولى بني لَيْث من هُوَ فَقَالَ لَا أعرفهُ"],[954,"قلت ليحيى أَبُو معشر النَّخعِيّ أحب إِلَيْك عَن إِبْرَاهِيم أَو مَنْصُور فَقَالَ مَنْصُور خير مِنْهُ وَمن أَبِيه"],[955,"قلت وَأَبُو يحيى القَتَّات كَيفَ حَدِيثه فَقَالَ ثِقَة"],[956,"قلت فَأَبُو ربيعَة فَقَالَ لَيْسَ لي بِهِ علم لَا أعرفهُ لم أكتب عَنهُ يَعْنِي زيد بن عَوْف الْبَصْرِيّ"],[957,"قلت فَأَبُو جناب القصاب فَقَالَ ثِقَة"],[958,"قلت وَأَبُو جزى فَقَالَ لَيْسَ بِشَيْء"],[959,"قلت ليحيى حَدثنَا بن يُونُس عَن أبي يزِيد الطَّحَّان من أَبُو يزِيد الطَّحَّان فَقَالَ لَا أعرفهُ"],[960,"وَسَأَلته عَن أبي مَالك النَّخعِيّ فَقَالَ ثِقَة"],[961,"قلت فَأَبُو سِنَان الشَّيْبَانِيّ فَقَالَ ثِقَة"],[962,"قلت فَأَبُو رِفَاعَة عَن الشّعبِيّ من هُوَ فَقَالَ هُوَ ثِقَة"],[963,"قلت فَأَبُو ليلى من هُوَ فَقَالَ لَيْسَ بِشَيْء قَالَ عُثْمَان وَهُوَ شيخ روى عَنهُ أَحْمد بن يُونُس"],[964,"قَالَ عُثْمَان كَانَ عَليّ بن الْمَدِينِيّ يسمع الْمَغَازِي من أَحْمد بن أَيُّوب"],[965,"قلت ليحيى سُلَيْمَان بن أبي سَلمَة فَقَالَ لَيْسَ بن أبي سَلمَة أَو مَا أرَاهُ بن أبي سَلمَة"],[966,"قَالَ وَسَأَلته عَن أبي نعَامَة السَّعْدِيّ فَقَالَ ثِقَة تمّ كتاب التَّارِيخ وَالْحَمْد لله على عونه وإحسانه وَصلى الله على سيدنَا مُحَمَّد النَّبِي وعَلى أَله وَسلم تَسْلِيمًا كثيرا حَسبنَا الله وَنعم الْوَكِيل وَافق الْفَرَاغ مِنْهُ صَاحبه مُحَمَّد بن أبي عبد الله بن جِبْرِيل بن مُحَمَّد بن عباد الْأنْصَارِيّ غفر الله لَهُ فِي اللَّيْلَة الَّتِي صبيحتها يَوْم الثُّلَاثَاء الْخَامِس وَالْعِشْرين من جُمَادَى الأول سنة ثَمَان وَعشْرين وسِتمِائَة أحسن الله خاتمتها قوبل حسب الطَّاقَة وَصَحَّ وَللَّه الْحَمد والْمنَّة"]]);
